  { id = "STURDY", n = 5, slug = "sturdy", name = "Sturdy", generation = 3, shortEffect = "Prevents being KOed from full HP, leaving 1 HP instead. Protects against the one-hit KO moves regardless of HP.", effect = "When this Pokémon is at full HP, any hit that would knock it out will instead leave it with 1 HP. Regardless of its current HP, it is also immune to the one-hit KO moves: Fissure, Guillotine, Horn Drill, and Sheer Cold. If this Pokémon is holding a Focus Sash, this ability takes precedence and the item will not be consumed.", species = 48, effectChanges = { { generation = 5, text = "One Hit KO moves have no effect when used on this Pokemon." } }, expressible = false },
