  { id = "SANDVEIL", n = 8, slug = "sand-veil", name = "Sand Veil", generation = 3, shortEffect = "Increases evasion to 1.25× during a sandstorm. Protects against sandstorm damage.", effect = "During a sandstorm, this Pokémon has 1.25× its evasion, and it does not take sandstorm damage regardless of type. The evasion bonus does not count as a stat modifier. Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in a sandstorm.", species = 30, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "stat_multiplier", stat = "evasion", factor = 1.25 } } }, expressible = false, notes = "in a sandstorm" },
  { id = "STATIC", n = 9, slug = "static", name = "Static", generation = 3, shortEffect = "Has a 30% chance of paralyzing attacking Pokémon on contact.", effect = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being paralyzed. Pokémon that are immune to Electric-type moves can still be paralyzed by this ability. Overworld: If the lead Pokémon has this ability, there is a 50% chance that encounters will be with an Electric Pokémon, if applicable.", species = 38, effectChanges = { { generation = 3, text = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being paralyzed. Pokémon that are immune to Electric-type moves can still be paralyzed by this ability." } }, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "inflict_status", status = "paralysis" } }, chance = 30 }, expressible = true },
  { id = "VOLTABSORB", n = 10, slug = "volt-absorb", name = "Volt Absorb", generation = 3, shortEffect = "Absorbs Electric moves, healing for 1/4 max HP.", effect = "Whenever an Electric-type move hits this Pokémon, it heals for 1/4 of its maximum HP, negating any other effect on it. This ability will not take effect if this Pokémon is Ground-type and thus immune to Electric moves. Electric moves will ignore this Pokémon's Substitute. This effect includes non-damaging moves, i.e. Thunder Wave.", species = 13, effectChanges = { { generation = 4, text = "This Pokemon is immune to damaging Electric-type moves and restores 1/4 of its maximum HP, rounded down, when hit by one." } }, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "type_immunity", moveType = "ELECTRIC" }, { kind = "heal", fraction = 0.25, when = "hit by an Electric-type move" } } }, expressible = true },
  { id = "WATERABSORB", n = 11, slug = "water-absorb", name = "Water Absorb", generation = 3, shortEffect = "Absorbs Water moves, healing for 1/4 max HP.", effect = "Whenever a Water-type move hits this Pokémon, it heals for 1/4 of its maximum HP, negating any other effect on it. Water moves will ignore this Pokémon's Substitute.", species = 30, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "type_immunity", moveType = "WATER" }, { kind = "heal", fraction = 0.25, when = "hit by a Water-type move" } } }, expressible = true },
  { id = "OBLIVIOUS", n = 12, slug = "oblivious", name = "Oblivious", generation = 3, shortEffect = "Prevents infatuation and protects against Captivate.", effect = "This Pokémon cannot be infatuated and is immune to Captivate. If a Pokémon is infatuated and acquires this ability, its infatuation is cleared.", species = 26, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "confusion" } } }, expressible = false, notes = "also blocks infatuation and Taunt" },
