  { id = "COMPOUNDEYES", n = 14, slug = "compound-eyes", name = "Compound Eyes", generation = 3, shortEffect = "Increases moves' accuracy to 1.3×.", effect = "This Pokémon's moves have 1.3× their accuracy. This ability has no effect on the one-hit KO moves (Fissure, Guillotine, Horn Drill, and Sheer Cold). Overworld: If the first Pokémon in the party has this ability, the chance of a wild Pokémon holding a particular item is raised from 50%, 5%, or 1% to 60%, 20%, or 5%, respectively.", species = 13, effectChanges = { { generation = 3, text = "This Pokémon's moves have 1.3× their accuracy. This ability has no effect on the one-hit KO moves (Fissure, Guillotine, Horn Drill, and Sheer Cold)." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "accuracy_multiplier", factor = 1.3 } } }, expressible = true },
  { id = "INSOMNIA", n = 15, slug = "insomnia", name = "Insomnia", generation = 3, shortEffect = "Prevents sleep.", effect = "This Pokémon cannot be asleep. This causes Rest to fail altogether. If a Pokémon is asleep and acquires this ability, it will immediately wake up; this includes when regaining a lost ability upon leaving battle. This ability functions identically to Vital Spirit in battle.", species = 24, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "sleep" } } }, expressible = true },
  { id = "COLORCHANGE", n = 16, slug = "color-change", name = "Color Change", generation = 3, shortEffect = "Changes type to match when hit by a damaging move.", effect = "Whenever this Pokémon takes damage from a move, the Pokémon's type changes to match the move. If the Pokémon has two types, both are overridden. The Pokémon must directly take damage; for example, moves blocked by a Substitute will not trigger this ability, nor will moves that deal damage indirectly, such as Spikes. This ability takes effect on only the last hit of a multiple-hit attack. In Pokémon Colosseum and XD: Gale of Darkness, this ability does not take effect on Shadow-type moves.", species = 1, effectChanges = { { generation = 5, text = "Whenever this Pokémon takes damage from a move, the Pokémon's type changes to match the move. If the Pokémon has two types, both are overridden. The Pokémon must directly take damage; for example, moves blocked by a Substitute will not trigger this ability, nor will moves that deal damage indirectly, such as Spikes. In Pokémon Colosseum and XD: Gale of Darkness, this ability does not take effect on Shadow-type moves." } }, expressible = false },
  { id = "IMMUNITY", n = 17, slug = "immunity", name = "Immunity", generation = 3, shortEffect = "Prevents poison.", effect = "This Pokémon cannot be poisoned. This includes bad poison. If a Pokémon is poisoned and acquires this ability, its poison is healed; this includes when regaining a lost ability upon leaving battle.", species = 4, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "poison" } } }, expressible = true },
  { id = "FLASHFIRE", n = 18, slug = "flash-fire", name = "Flash Fire", generation = 3, shortEffect = "Protects against Fire moves. Once one has been blocked, the Pokémon's own Fire moves inflict 1.5× damage until it leaves battle.", effect = "This Pokémon is immune to Fire-type moves. Once this Pokémon has been hit by a Fire move, its own Fire moves will inflict 1.5× as much damage until it leaves battle. This ability has no effect while the Pokémon is frozen. The Fire damage bonus is retained even if the Pokémon is frozen and thawed or the ability is lost or disabled. Fire moves will ignore this Pokémon's Substitute. This ability takes effect even on non-damaging moves, i.e. Will-O-Wisp.", species = 29, effectChanges = { { generation = 4, text = "This Pokemon is immune to Fire-type moves, as long as it is not frozen. The first time it is hit by a Fire-type move, damage from its Fire-type attacks will be multiplied by 1.5 as long as it remains active and has this Ability. If this Pokemon has a non-volatile status condition, is a Fire type, or has a substitute, Will-O-Wisp will not activate this Ability." } }, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "type_immunity", moveType = "FIRE" }, { kind = "damage_dealt_multiplier", factor = 1.5, moveType = "FIRE" } } }, expressible = false, notes = "the boost only after a Fire move has hit it" },
  { id = "SHIELDDUST", n = 19, slug = "shield-dust", name = "Shield Dust", generation = 3, shortEffect = "Protects against incoming moves' extra effects.", effect = "This Pokémon is immune to the extra effects of moves used against it. An extra effect is a move's chance, listed as an \"effect chance\", to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move's main effect. For example, Thunder Shock's paralysis is an extra effect, but Thunder Wave's is not, nor are Knock Off's item removal and Air Cutter's increased critical hit rate.", species = 12, expressible = false },
  { id = "OWNTEMPO", n = 20, slug = "own-tempo", name = "Own Tempo", generation = 3, shortEffect = "Prevents confusion.", effect = "This Pokémon cannot be confused. If a Pokémon is confused and acquires this ability, its confusion will immediately be healed.", species = 33, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "confusion" } } }, expressible = true },
  { id = "SUCTIONCUPS", n = 21, slug = "suction-cups", name = "Suction Cups", generation = 3, shortEffect = "Prevents being forced out of battle by other Pokémon's moves.", effect = "This Pokémon cannot be forced out of battle by moves such as Whirlwind. Dragon Tail and Circle Throw still inflict damage against this Pokémon. Overworld: If the lead Pokémon has this ability, the success rate while fishing is increased.", species = 5, effectChanges = { { generation = 3, text = "This Pokémon cannot be forced out of battle by moves such as Whirlwind. Dragon Tail and Circle Throw still inflict damage against this Pokémon." } }, expressible = false },
  { id = "INTIMIDATE", n = 22, slug = "intimidate", name = "Intimidate", generation = 3, shortEffect = "Lowers opponents' Attack one stage upon entering battle.", effect = "When this Pokémon enters battle, the opponent's Attack is lowered by one stage. In a double battle, both opponents are affected. This ability also takes effect when acquired during a battle, but will not take effect again if lost and reobtained without leaving battle. This ability has no effect on an opponent that has a Substitute. Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped.", species = 47, effectChanges = { { generation = 3, text = "When this Pokémon enters battle, the opponent's Attack is lowered by one stage. In a double battle, both opponents are affected. This ability has no effect on an opponent that has a Substitute." }, { generation = 4, text = "When this Pokémon enters battle, the opponent's Attack is lowered by one stage. In a double battle, both opponents are affected. This ability has no effect on an opponent that has a Substitute. Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped." } }, behaviour = { trigger = "switch_in", scope = "foes", effects = { { kind = "stat_change", stat = "attack", stages = -1 } } }, expressible = true },
  { id = "SHADOWTAG", n = 23, slug = "shadow-tag", name = "Shadow Tag", generation = 3, shortEffect = "Prevents opponents from fleeing or switching out.", effect = "While this Pokémon is in battle, opposing Pokémon cannot flee or switch out. Other Pokémon with this ability are unaffected. Pokémon with Run Away can still flee. Pokémon can still switch out with the use of a move or item.", species = 6, effectChanges = { { generation = 4, text = "While this Pokémon is in battle, opposing Pokémon cannot flee or switch out. Pokémon with Run Away can still flee." } }, expressible = false },
  { id = "ROUGHSKIN", n = 24, slug = "rough-skin", name = "Rough Skin", generation = 3, shortEffect = "Damages attacking Pokémon for 1/8 their max HP on contact.", effect = "Whenever a move makes contact with this Pokémon, the move's user takes 1/8 of its maximum HP in damage. This ability functions identically to Iron Barbs.", species = 6, effectChanges = { { generation = 4, text = "Whenever a move makes contact with this Pokémon, the move's user takes 1/16 of its maximum HP in damage." } }, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "damage", fraction = 0.125 } } }, expressible = true },
  { id = "WONDERGUARD", n = 25, slug = "wonder-guard", name = "Wonder Guard", generation = 3, shortEffect = "Protects against damaging moves that are not super effective.", effect = "This Pokémon is immune to damaging moves that are not super effective against it. Moves that inflict fixed damage, such as Night Shade or Seismic Toss, are considered super effective if their types are. Damage not directly dealt by moves, such as damage from weather, a status ailment, or Spikes, is not prevented. This ability cannot be copied with Role Play or traded away with Skill Swap, but it can be copied with Trace, disabled with Gastro Acid, or changed with Worry Seed. This Pokémon can still use Role Play itself to lose this ability, but not Skill Swap. If this Pokémon has a Substitute, this ability will block moves as usual and any moves not blocked will react to the Substitute as usual.", species = 1, effectChanges = { { generation = 5, text = "This Pokemon is only damaged by Fire Fang, supereffective moves, indirect damage." } }, expressible = false },
  { id = "LEVITATE", n = 26, slug = "levitate", name = "Levitate", generation = 3, shortEffect = "Evades Ground moves.", effect = "This Pokémon is immune to Ground-type moves, Spikes, Toxic Spikes, and Arena Trap. This ability is disabled during Gravity or Ingrain, or while holding an Iron Ball. This ability is not disabled during Roost.", species = 45, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "type_immunity", moveType = "GROUND" } } }, expressible = true },
  { id = "EFFECTSPORE", n = 27, slug = "effect-spore", name = "Effect Spore", generation = 3, shortEffect = "Has a 30% chance of inflcting either paralysis, poison, or sleep on attacking Pokémon on contact.", effect = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being paralyzed, poisoned, or put to sleep, chosen at random. Nothing is done to compensate if the move's user is immune to one of these ailments; there is simply a lower chance that the move's user will be affected.", species = 11, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "inflict_status", status = "poison" }, { kind = "inflict_status", status = "paralysis" }, { kind = "inflict_status", status = "sleep" } }, chance = 30 }, expressible = false, notes = "one of the three" },
  { id = "SYNCHRONIZE", n = 28, slug = "synchronize", name = "Synchronize", generation = 3, shortEffect = "Copies burns, paralysis, and poison received onto the Pokémon that inflicted them.", effect = "Whenever this Pokémon is burned, paralyzed, or poisoned, the Pokémon who gave this Pokémon that ailment is also given the ailment. This ability passes back bad poison when this Pokémon is badly poisoned. This ability cannot pass on a status ailment that the Pokémon did not directly receive from another Pokémon, such as the poison from Toxic Spikes or the burn from a Flame Orb. Overworld: If the lead Pokémon has this ability, wild Pokémon have a 50% chance of having the lead Pokémon's nature, and a 50% chance of being given a random nature as usual, including the lead Pokémon's nature. This does not work on Pokémon received outside of battle or roaming legendaries.", species = 18, effectChanges = { { generation = 3, text = "Whenever this Pokémon is burned, paralyzed, or poisoned, the Pokémon who gave this Pokémon that ailment is also given the ailment." }, { generation = 4, text = "Whenever this Pokémon is burned, paralyzed, or poisoned, the Pokémon who gave this Pokémon that ailment is also given the ailment. This ability passes back bad poison when this Pokémon is badly poisoned. This ability cannot pass on a status ailment that the Pokémon did not directly receive from another Pokémon, such as the poison from Toxic Spikes or the burn from a Flame Orb. Overworld: If the lead Pokémon has this ability, wild Pokémon have a 50% chance of having the lead Pokémon's nature, and a 50% chance of being given a random nature as usual, including the lead Pokémon's nature. This does not work on Pokémon received outside of battle, static encounters, or roaming legendaries." }, { generation = 5, text = "Whenever this Pokémon is burned, paralyzed, or poisoned, the Pokémon who gave this Pokémon that ailment is also given the ailment. This ability passes back badly poisoned as regular poison. This ability cannot pass on a status ailment that the Pokémon did not directly receive from another Pokémon, such as the poison from Toxic Spikes or the burn from a Flame Orb. Overworld: If the lead Pokémon has this ability, wild Pokémon have a 50% chance of having the lead Pokémon's nature, and a 50% chance of being given a random nature as usual, including the lead Pokémon's nature. This does not work on Pokémon received outside of battle or roaming legendaries." } }, expressible = false },
  { id = "CLEARBODY", n = 29, slug = "clear-body", name = "Clear Body", generation = 3, shortEffect = "Prevents stats from being lowered by other Pokémon.", effect = "This Pokémon cannot have its stats lowered by other Pokémon. This ability does not prevent any stat losses other than stat modifiers, such as the Speed cut from paralysis. This Pokémon can still be passed negative stat modifiers through Guard Swap, Heart Swap, or Power Swap. This ability functions identically to White Smoke in battle.", species = 19, expressible = false },
  { id = "NATURALCURE", n = 30, slug = "natural-cure", name = "Natural Cure", generation = 3, shortEffect = "Cures any major status ailment upon switching out.", effect = "This Pokémon is cured of any major status ailment when it is switched out for another Pokémon. If this ability is acquired during battle, the Pokémon is cured upon leaving battle before losing the temporary ability.", species = 19, behaviour = { trigger = "on_switch_out", scope = "self", effects = {  } }, expressible = false, notes = "cures its status when it switches out" },
  { id = "LIGHTNINGROD", n = 31, slug = "lightning-rod", name = "Lightning Rod", generation = 3, shortEffect = "Redirects single-target Electric moves to this Pokémon where possible. Absorbs Electric moves, raising Special Attack one stage.", effect = "All other Pokémon's single-target Electric-type moves are redirected to this Pokémon if it is an eligible target. Other Pokémon's Electric moves raise this Pokémon's Special Attack one stage, negating any other effect on it, and cannot miss it. If the move's intended target also has this ability, the move is not redirected. When multiple Pokémon with this ability are possible targets for redirection, the move is redirected to the one with the highest Speed stat, or, in the case of a tie, to a random tied Pokémon. Follow Me takes precedence over this ability. If the Pokémon is a Ground-type and thus immune to Electric moves, its immunity prevents the Special Attack boost.", species = 37, effectChanges = { { generation = 3, text = "If this Pokemon is not the target of a single-target Electric-type move used by another Pokemon, this Pokemon redirects that move to itself. Does not redirect Hidden Power." }, { generation = 4, text = "If this Pokemon is not the target of a single-target Electric-type move used by another Pokemon, this Pokemon redirects that move to itself. Does not redirect Hidden Power. Overworld: Increases the frequency of Match Call calls on the overworld if any party Pokémon has this ability." }, { generation = 5, text = "If this Pokemon is not the target of a single-target Electric-type move used by another Pokemon, this Pokemon redirects that move to itself. Does not redirect Hidden Power or Judgement." } }, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "type_immunity", moveType = "ELECTRIC" }, { kind = "stat_change", stat = "special-attack", stages = 1, when = "hit by an Electric-type move" } } }, expressible = false, notes = "also draws Electric moves to itself" },
  { id = "SERENEGRACE", n = 32, slug = "serene-grace", name = "Serene Grace", generation = 3, shortEffect = "Doubles the chance of moves' extra effects occurring.", effect = "This Pokémon's moves have twice their usual effect chance. An effect chance is a move's chance to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move's main effect. For example, Flamethrower's chance of burning the target is doubled, but Protect's chance of success and Air Cutter's increased critical hit rate are unaffected. Secret Power is unaffected.", species = 15, expressible = false },
  { id = "SWIFTSWIM", n = 33, slug = "swift-swim", name = "Swift Swim", generation = 3, shortEffect = "Doubles Speed during rain.", effect = "This Pokémon's Speed is doubled during rain. This bonus does not count as a stat modifier.", species = 48, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "stat_multiplier", stat = "speed", factor = 2 } } }, expressible = false, notes = "in rain" },
  { id = "CHLOROPHYLL", n = 34, slug = "chlorophyll", name = "Chlorophyll", generation = 3, shortEffect = "Doubles Speed during strong sunlight.", effect = "This Pokémon's Speed is doubled during strong sunlight. This bonus does not count as a stat modifier.", species = 39, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "stat_multiplier", stat = "speed", factor = 2 } } }, expressible = false, notes = "in harsh sunlight" },
