  { id = "TRACE", n = 36, slug = "trace", name = "Trace", generation = 3, shortEffect = "Copies an opponent's ability upon entering battle.", effect = "When this Pokémon enters battle, it copies a random opponent's ability. This ability cannot copy Flower Gift, Forecast, Illusion, Imposter, Multitype, Trace, or Zen Mode.", species = 8, effectChanges = { { generation = 5, text = "When this Pokémon enters battle, it copies a random opponent's ability. This ability cannot copy Forecast, Multitype, or Trace." }, { generation = 4, text = "When this Pokémon enters battle, it copies a random opponent's ability." } }, expressible = false },
  { id = "HUGEPOWER", n = 37, slug = "huge-power", name = "Huge Power", generation = 3, shortEffect = "Doubles Attack in battle.", effect = "This Pokémon's Attack is doubled while in battle. This bonus does not count as a stat modifier. This ability functions identically to Pure Power.", species = 7, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_multiplier", stat = "attack", factor = 2 } } }, expressible = true },
  { id = "POISONPOINT", n = 38, slug = "poison-point", name = "Poison Point", generation = 3, shortEffect = "Has a 30% chance of poisoning attacking Pokémon on contact.", effect = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being poisoned.", species = 20, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "inflict_status", status = "poison" } }, chance = 30 }, expressible = true },
