  { id = "MAGMAARMOR", n = 40, slug = "magma-armor", name = "Magma Armor", generation = 3, shortEffect = "Prevents freezing.", effect = "This Pokémon cannot be frozen. If a Pokémon is frozen and acquires this ability, it will immediately thaw out; this includes when regaining a lost ability upon leaving battle. Overworld: If any Pokémon in the party has this ability, each egg in the party has its hatch counter decreased by 2 (rather than 1) each step cycle, making eggs hatch roughly twice as quickly. This effect does not stack if multiple Pokémon have this ability or Flame Body.", species = 3, effectChanges = { { generation = 3, text = "This Pokémon cannot be frozen. If a Pokémon is frozen and acquires this ability, it will immediately thaw out; this includes when regaining a lost ability upon leaving battle." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "freeze" } } }, expressible = true },
  { id = "WATERVEIL", n = 41, slug = "water-veil", name = "Water Veil", generation = 3, shortEffect = "Prevents burns.", effect = "This Pokémon cannot be burned. If a Pokémon is burned and acquires this ability, its burn is healed; this includes when regaining a lost ability upon leaving battle.", species = 13, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "burn" } } }, expressible = true },
  { id = "MAGNETPULL", n = 42, slug = "magnet-pull", name = "Magnet Pull", generation = 3, shortEffect = "Prevents Steel opponents from fleeing or switching out.", effect = "While this Pokémon is in battle, opposing Steel-type Pokémon cannot flee or switch out. Pokémon with Run Away can still flee. Pokémon can still switch out with the use of a move or item. Overworld: If the lead Pokémon has this ability, Steel-type Pokémon have a higher encounter rate.", species = 9, effectChanges = { { generation = 3, text = "While this Pokémon is in battle, opposing Steel-type Pokémon cannot flee or switch out. Pokémon with Run Away can still flee. Pokémon can still switch out with the use of a move or item." } }, expressible = false },
  { id = "SOUNDPROOF", n = 43, slug = "soundproof", name = "Soundproof", generation = 3, shortEffect = "Protects against sound-based moves.", effect = "This Pokémon is immune to moves flagged as being sound-based. Heal Bell is unaffected. Uproar still prevents this Pokémon from sleeping. This Pokémon can still receive a Perish Song counter through Baton Pass, and will retain a Perish Song counter if it acquires this ability after Perish Song is used. Howl, Roar of Time, Sonic Boom, and Yawn are not flagged as sound-based.", species = 18, effectChanges = { { generation = 5, text = "This Pokémon is immune to moves flagged as being sound-based. Prevents Heal Bell from curing the Pokémon, whether or not it is in battle. Uproar still prevents this Pokémon from sleeping. This Pokémon can still receive a Perish Song counter through Baton Pass, and will retain a Perish Song counter if it acquires this ability after Perish Song is used. Howl, Roar of Time, Sonic Boom, and Yawn are not flagged as sound-based." } }, expressible = false },
  { id = "RAINDISH", n = 44, slug = "rain-dish", name = "Rain Dish", generation = 3, shortEffect = "Heals for 1/16 max HP after each turn during rain.", effect = "This Pokémon heals for 1/16 of its maximum HP after each turn during rain.", species = 14, behaviour = { trigger = "turn_end", scope = "self", effects = { { kind = "heal", fraction = 0.0625, when = "each turn in rain" } } }, expressible = true },
  { id = "SANDSTREAM", n = 45, slug = "sand-stream", name = "Sand Stream", generation = 3, shortEffect = "Summons a sandstorm that lasts indefinitely upon entering battle.", effect = "The weather changes to a sandstorm when this Pokémon enters battle and does not end unless cancelled by another weather condition. If multiple Pokémon with this ability, Drizzle, Drought, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room. Each ability's weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay. Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in a sandstorm.", species = 5, behaviour = { trigger = "switch_in", scope = "field", effects = { { kind = "set_weather", weather = "sandstorm" } } }, expressible = true },
  { id = "PRESSURE", n = 46, slug = "pressure", name = "Pressure", generation = 3, shortEffect = "Increases the PP cost of moves targetting the Pokémon by one.", effect = "Moves targetting this Pokémon use one extra PP. This ability stacks if multiple targets have it. This ability still affects moves that fail or miss. This ability does not affect ally moves that target either the entire field or just its side, nor this Pokémon's self-targetted moves; it does, however, affect single-targetted ally moves aimed at this Pokémon, ally moves that target all other Pokémon, and opponents' moves that target the entire field. If this ability raises a move's PP cost above its remaining PP, it will use all remaining PP. When this Pokémon enters battle, all participating trainers are notified that it has this ability. Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.", species = 36, effectChanges = { { generation = 3, text = "Moves targetting this Pokémon use one extra PP. This ability stacks if multiple targets have it. This ability still affects moves that fail or miss. This ability does not affect ally moves that target either the entire field or just its side, nor this Pokémon's self-targetted moves; it does, however, affect single-targetted ally moves aimed at this Pokémon, ally moves that target all other Pokémon, and opponents' moves that target the entire field. If this ability raises a move's PP cost above its remaining PP, it will use all remaining PP. When this Pokémon enters battle, all participating trainers are notified that it has this ability." }, { generation = 4, text = "Moves targetting this Pokémon use one extra PP. This ability stacks if multiple targets have it. This ability still affects moves that fail or miss. This ability does not affect friendly Pokémon's moves that target all other Pokémon, nor this Pokémon's self-targetted moves; it does, however, affect single-targetted ally moves aimed at this Pokémon, ally moves that target all other Pokémon, and opponents' moves that target the entire field. If this ability raises a move's PP cost above its remaining PP, it will use all remaining PP." } }, expressible = false },
  { id = "THICKFAT", n = 47, slug = "thick-fat", name = "Thick Fat", generation = 3, shortEffect = "Halves damage from Fire and Ice moves.", effect = "This Pokémon takes half as much damage from Fire- and Ice-type moves.", species = 33, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_taken_multiplier", factor = 0.5, moveType = "FIRE" }, { kind = "damage_taken_multiplier", factor = 0.5, moveType = "ICE" } } }, expressible = true },
  { id = "EARLYBIRD", n = 48, slug = "early-bird", name = "Early Bird", generation = 3, shortEffect = "Makes sleep pass twice as quickly.", effect = "This Pokémon's remaining sleep turn count falls by 2 rather than 1. If this Pokémon's sleep counter is at 1, it will fall to 0 and then the Pokémon will wake up.", species = 16, expressible = false },
  { id = "FLAMEBODY", n = 49, slug = "flame-body", name = "Flame Body", generation = 3, shortEffect = "Has a 30% chance of burning attacking Pokémon on contact.", effect = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being burned. Overworld: If any Pokémon in the party has this ability, each egg in the party has its hatch counter decreased by 2 (rather than 1) each step cycle, making eggs hatch roughly twice as quickly. This effect does not stack if multiple Pokémon have this ability or Magma Armor.", species = 23, effectChanges = { { generation = 3, text = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being burned." } }, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "inflict_status", status = "burn" } }, chance = 30 }, expressible = true },
  { id = "RUNAWAY", n = 50, slug = "run-away", name = "Run Away", generation = 3, shortEffect = "Ensures success fleeing from wild battles.", effect = "This Pokémon is always successful fleeing from wild battles, even if trapped by a move or ability.", species = 36, expressible = false },
  { id = "KEENEYE", n = 51, slug = "keen-eye", name = "Keen Eye", generation = 3, shortEffect = "Prevents accuracy from being lowered.", effect = "This Pokémon cannot have its accuracy lowered. This ability does not prevent any accuracy losses other than stat modifiers, such as the accuracy cut from fog; nor does it prevent other Pokémon's evasion from making this Pokémon's moves less accurate. This Pokémon can still be passed negative accuracy modifiers through Heart Swap. Overworld: If the first Pokémon in the party has this ability, any random encounter with a Pokémon five or more levels lower than it has a 50% chance of being skipped.", species = 43, effectChanges = { { generation = 3, text = "This Pokémon cannot have its accuracy lowered. This ability does not prevent other Pokémon's evasion from making this Pokémon's moves less accurate." } }, expressible = false },
  { id = "HYPERCUTTER", n = 52, slug = "hyper-cutter", name = "Hyper Cutter", generation = 3, shortEffect = "Prevents Attack from being lowered by other Pokémon.", effect = "This Pokémon's Attack cannot be lowered by other Pokémon. This ability does not prevent any Attack losses other than stat modifiers, such as the Attack cut from a burn. This Pokémon can still be passed negative Attack modifiers through Heart Swap or Power Swap.", species = 12, effectChanges = { { generation = 3, text = "This Pokémon's Attack cannot be lowered by other Pokémon. This ability does not prevent any Attack losses other than stat modifiers, such as the Attack cut from a burn." }, { generation = 4, text = "This Pokémon's Attack cannot be lowered by other Pokémon. This ability does not prevent any Attack losses other than stat modifiers, such as the Attack cut from a burn. Overworld: Doubles Cut's grass-cutting radius on the overworld if any party Pokémon has this ability." } }, expressible = false },
  { id = "PICKUP", n = 53, slug = "pickup", name = "Pickup", generation = 3, shortEffect = "Picks up other Pokémon's used and Flung held items. May also pick up an item after battle.", effect = "At the end of each turn, if another Pokémon consumed or Flung a held item that turn, this Pokémon picks up the item if it is not already holding one. After each battle, this Pokémon has a 10% chance of picking up an item if it is not already holding one. The Air Balloon and Eject Button cannot be picked up. The items that may be found vary by game, and, since Pokémon Emerald, by the Pokémon's level. This ability is checked after the battle ends, at which point any temporary ability changes have worn off.", species = 30, effectChanges = { { generation = 5, text = "After each battle, this Pokémon has a 10% chance of picking up an item if it is not already holding one. The items that may be found vary by game, and, since Pokémon Emerald, by the Pokémon's level. This ability is checked after the battle ends, at which point any temporary ability changes have worn off." } }, expressible = false },
  { id = "TRUANT", n = 54, slug = "truant", name = "Truant", generation = 3, shortEffect = "Skips every second turn.", effect = "Every second turn on which this Pokémon should attempt to use a move, it will instead do nothing (\"loaf around\"). Loafing around interrupts moves that take multiple turns the same way paralysis, flinching, etc do. Most such moves, for example Bide or Rollout, are simply cut off upon loafing around. Attacks with a recharge turn, such as Hyper Beam, do not have to recharge; attacks with a preparation turn, such as Fly, do not end up being used. Moves that are forced over multiple turns and keep going through failure, such as Outrage, Uproar, or any move forced by Encore, keep going as usual. If this Pokémon is confused, its confusion is not checked when loafing around; the Pokémon cannot hurt itself, and its confusion does not end or come closer to ending. If this Pokémon attempts to move but fails, e.g. because of paralysis or Gravity, it still counts as having moved and will loaf around the next turn. If it does not attempt to move, e.g. because it is asleep or frozen, whatever it would have done will be postponed until its next attempt; that is, it will either loaf around or move as usual, depending on what it last did. This ability cannot be changed with Worry Seed, but it can be disabled with Gastro Acid, changed with Role Play, or traded away with Skill Swap.", species = 3, expressible = false },
  { id = "HUSTLE", n = 55, slug = "hustle", name = "Hustle", generation = 3, shortEffect = "Strengthens physical moves to inflict 1.5× damage, but decreases their accuracy to 0.8×.", effect = "This Pokémon's physical moves do 1.5× as much regular damage, but have 0.8× their usual accuracy. Special moves are unaffected. Moves that do set damage, such as Seismic Toss, have their accuracy affected, but not their damage. Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.", species = 30, effectChanges = { { generation = 3, text = "This Pokémon's physical moves do 1.5× as much regular damage, but have 0.8× their usual accuracy. Special moves are unaffected. Moves that do set damage, such as Seismic Toss, have their accuracy affected, but not their damage." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.5 }, { kind = "accuracy_multiplier", factor = 0.8 } } }, expressible = false, notes = "physical moves only" },
  { id = "CUTECHARM", n = 56, slug = "cute-charm", name = "Cute Charm", generation = 3, shortEffect = "Has a 30% chance of infatuating attacking Pokémon on contact.", effect = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being infatuated. Overworld: If the first Pokémon in the party has this ability, any wild Pokémon whose species can be either gender has a 2/3 chance of being set to the opposite gender, and a 1/3 chance of having a random gender as usual.", species = 15, effectChanges = { { generation = 3, text = "Whenever a move makes contact with this Pokémon, the move's user has a 30% chance of being infatuated." } }, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "inflict_status", status = "infatuation" } }, chance = 30 }, expressible = true },
  { id = "PLUS", n = 57, slug = "plus", name = "Plus", generation = 3, shortEffect = "Increases Special Attack to 1.5× when a friendly Pokémon has Plus or Minus.", effect = "This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus or Minus. This bonus does not count as a stat modifier. If either ability is disabled by Gastro Acid, both lose their effect.", species = 10, effectChanges = { { generation = 5, text = "This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Minus." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_multiplier", stat = "special-attack", factor = 1.5 } } }, expressible = false, notes = "with an ally that has Plus or Minus" },
  { id = "MINUS", n = 58, slug = "minus", name = "Minus", generation = 3, shortEffect = "Increases Special Attack to 1.5× when a friendly Pokémon has Plus or Minus.", effect = "This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus or Minus. This bonus does not count as a stat modifier. If either ability is disabled by Gastro Acid, both lose their effect.", species = 8, effectChanges = { { generation = 5, text = "This Pokémon has 1.5× its Special Attack if any friendly Pokémon has Plus." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_multiplier", stat = "special-attack", factor = 1.5 } } }, expressible = false, notes = "with an ally that has Plus or Minus" },
  { id = "FORECAST", n = 59, slug = "forecast", name = "Forecast", generation = 3, shortEffect = "Changes Castform's type and form to match the weather.", effect = "During rain, strong sunlight, or hail, this Pokémon's type changes to Water, Fire, or Ice, respectively, and its form changes to match. This ability has no effect for any Pokémon other than Castform. If the weather ends or becomes anything that does not trigger this ability, or a Pokémon with Air Lock or Cloud Nine enters battle, this Pokémon's type and form revert to their default. If this ability is lost or disabled, this Pokémon cannot change its current type and form until it regains its ability.", species = 4, expressible = false },
  { id = "STICKYHOLD", n = 60, slug = "sticky-hold", name = "Sticky Hold", generation = 3, shortEffect = "Prevents a held item from being removed by other Pokémon.", effect = "This Pokémon's hold item cannot be removed by other Pokémon. Damaging moves that would remove this Pokémon's item can still inflict damage against this Pokémon, e.g. Knock Off or Pluck. This Pokémon can still use moves that involve the loss of its own item, e.g. Fling or Trick. Overworld: If the lead Pokémon has this ability, the encounter rate while fishing is increased.", species = 10, effectChanges = { { generation = 3, text = "This Pokémon's hold item cannot be removed by other Pokémon. Damaging moves that would remove this Pokémon's item can still inflict damage against this Pokémon, e.g. Knock Off. This Pokémon can still use moves that involve the loss of its own item, e.g. Fling or Trick." } }, expressible = false },
  { id = "SHEDSKIN", n = 61, slug = "shed-skin", name = "Shed Skin", generation = 3, shortEffect = "Has a 33% chance of curing any major status ailment after each turn.", effect = "After each turn, this Pokémon has a 33% of being cured of any major status ailment.", species = 21, effectChanges = { { generation = 5, text = "After each turn, this Pokémon has a 30% of being cured of any major status ailment." }, { generation = 4, text = "After each turn, this Pokémon has a 33% of being cured of any major status ailment." } }, behaviour = { trigger = "turn_end", scope = "self", effects = {  }, chance = 33 }, expressible = true },
  { id = "GUTS", n = 62, slug = "guts", name = "Guts", generation = 3, shortEffect = "Increases Attack to 1.5× with a major status ailment.", effect = "Whenever this Pokémon is asleep, burned, paralyzed, or poisoned, it has 1.5× its Attack. This Pokémon is not affected by the usual Attack cut from a burn. This bonus does not count as a stat modifier.", species = 26, effectChanges = { { generation = 4, text = "Whenever this Pokémon is burned, paralyzed, or poisoned, it has 1.5× its Attack. This Pokémon is not affected by the usual Attack cut from a burn. This bonus does not count as a stat modifier." } }, behaviour = { trigger = "on_status", scope = "self", effects = { { kind = "stat_multiplier", stat = "attack", factor = 1.5 } } }, expressible = false, notes = "with a status condition" },
  { id = "MARVELSCALE", n = 63, slug = "marvel-scale", name = "Marvel Scale", generation = 3, shortEffect = "Increases Defense to 1.5× with a major status ailment.", effect = "Whenever this Pokémon has a major status ailment, it has 1.5× its Defense. This bonus does not count as a stat modifier.", species = 3, behaviour = { trigger = "on_status", scope = "self", effects = { { kind = "stat_multiplier", stat = "defense", factor = 1.5 } } }, expressible = false, notes = "with a status condition" },
  { id = "LIQUIDOOZE", n = 64, slug = "liquid-ooze", name = "Liquid Ooze", generation = 3, shortEffect = "Damages opponents using leeching moves for as much as they would heal.", effect = "Whenever a Pokémon would heal after hitting this Pokémon with a leeching move like Absorb, it instead loses as many HP as it would usually gain. Dream Eater is unaffected.", species = 4, expressible = false },
  { id = "OVERGROW", n = 65, slug = "overgrow", name = "Overgrow", generation = 3, shortEffect = "Strengthens Grass moves to inflict 1.5× damage at 1/3 max HP or less.", effect = "When this Pokémon has 1/3 or less of its HP remaining, its Grass-type moves inflict 1.5× as much regular damage.", species = 32, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.5, moveType = "GRASS", when = "HP at or below 1/3" } } }, expressible = false, notes = "at 1/3 HP or less" },
  { id = "BLAZE", n = 66, slug = "blaze", name = "Blaze", generation = 3, shortEffect = "Strengthens Fire moves to inflict 1.5× damage at 1/3 max HP or less.", effect = "When this Pokémon has 1/3 or less of its HP remaining, its Fire-type moves inflict 1.5× as much regular damage.", species = 32, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.5, moveType = "FIRE", when = "HP at or below 1/3" } } }, expressible = false, notes = "at 1/3 HP or less" },
  { id = "TORRENT", n = 67, slug = "torrent", name = "Torrent", generation = 3, shortEffect = "Strengthens Water moves to inflict 1.5× damage at 1/3 max HP or less.", effect = "When this Pokémon has 1/3 or less of its HP remaining, its Water-type moves inflict 1.5× as much regular damage.", species = 32, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.5, moveType = "WATER", when = "HP at or below 1/3" } } }, expressible = false, notes = "at 1/3 HP or less" },
  { id = "SWARM", n = 68, slug = "swarm", name = "Swarm", generation = 3, shortEffect = "Strengthens Bug moves to inflict 1.5× damage at 1/3 max HP or less.", effect = "When this Pokémon has 1/3 or less of its HP remaining, its Bug-type moves inflict 1.5× as much regular damage. Overworld: If the lead Pokémon has this ability, the wild encounter rate is increased.", species = 32, effectChanges = { { generation = 3, text = "When this Pokémon has 1/3 or less of its HP remaining, its Bug-type moves inflict 1.5× as much regular damage." }, { generation = 4, text = "When this Pokémon has 1/3 or less of its HP remaining, its Bug-type moves inflict 1.5× as much regular damage. Overworld: Increases the frequency of cries heard on the overworld if any party Pokémon has this ability." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.5, moveType = "BUG", when = "HP at or below 1/3" } } }, expressible = false, notes = "at 1/3 HP or less" },
  { id = "ROCKHEAD", n = 69, slug = "rock-head", name = "Rock Head", generation = 3, shortEffect = "Protects against recoil damage.", effect = "This Pokémon does not receive recoil damage from its recoil moves. Struggle's recoil is unaffected. This ability does not prevent crash damage from missing with Jump Kick or High Jump Kick.", species = 24, expressible = false },
  { id = "DROUGHT", n = 70, slug = "drought", name = "Drought", generation = 3, shortEffect = "Summons strong sunlight that lasts indefinitely upon entering battle.", effect = "The weather changes to strong sunlight when this Pokémon enters battle and does not end unless cancelled by another weather condition. If multiple Pokémon with this ability, Drizzle, Sand Stream, or Snow Warning are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room. Each ability's weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.", species = 5, behaviour = { trigger = "switch_in", scope = "field", effects = { { kind = "set_weather", weather = "sun" } } }, expressible = true },
  { id = "ARENATRAP", n = 71, slug = "arena-trap", name = "Arena Trap", generation = 3, shortEffect = "Prevents opponents from fleeing or switching out. Eluded by Flying-types and Pokémon in the air.", effect = "While this Pokémon is in battle, opposing Pokémon cannot flee or switch out. Flying-type Pokémon and Pokémon in the air, e.g. due to Levitate or Magnet Rise, are unaffected. Pokémon with Run Away can still flee. Pokémon can still switch out with the use of a move or item. Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.", species = 3, effectChanges = { { generation = 3, text = "While this Pokémon is in battle, opposing Pokémon cannot flee or switch out. Flying-type Pokémon and Pokémon in the air, e.g. due to Levitate are unaffected. Pokémon with Run Away can still flee. Pokémon can still switch out with the use of a move or item." } }, expressible = false },
  { id = "VITALSPIRIT", n = 72, slug = "vital-spirit", name = "Vital Spirit", generation = 3, shortEffect = "Prevents sleep.", effect = "This Pokémon cannot be asleep. This causes Rest to fail altogether. If a Pokémon is asleep and acquires this ability, it will immediately wake up; this includes when regaining a lost ability upon leaving battle. This ability functions identically to Insomnia in battle. Overworld: If the lead Pokémon has this ability, higher-levelled Pokémon have their encounter rate increased.", species = 16, effectChanges = { { generation = 3, text = "This Pokémon cannot be asleep. This causes Rest to fail altogether. If a Pokémon is asleep and acquires this ability, it will immediately wake up; this includes when regaining a lost ability upon leaving battle. This ability functions identically to Insomnia in battle." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "sleep" } } }, expressible = true },
  { id = "WHITESMOKE", n = 73, slug = "white-smoke", name = "White Smoke", generation = 3, shortEffect = "Prevents stats from being lowered by other Pokémon.", effect = "This Pokémon cannot have its stats lowered by other Pokémon. This ability does not prevent any stat losses other than stat modifiers, such as the Speed cut from paralysis; nor self-inflicted stat drops, such as the Special Attack drop from Overheat; nor opponent-triggered stat boosts, such as the Attack boost from Swagger. This Pokémon can still be passed negative stat modifiers through Guard Swap, Heart Swap, or Power Swap. This ability functions identically to Clear Body in battle. Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved.", species = 5, effectChanges = { { generation = 3, text = "This Pokémon cannot have its stats lowered by other Pokémon. This ability does not prevent any stat losses other than stat modifiers, such as the Speed cut from paralysis; nor self-inflicted stat drops, such as the Special Attack drop from Overheat; nor opponent-triggered stat boosts, such as the Attack boost from Swagger. This ability functions identically to Clear Body in battle." } }, expressible = false },
  { id = "PUREPOWER", n = 74, slug = "pure-power", name = "Pure Power", generation = 3, shortEffect = "Doubles Attack in battle.", effect = "This Pokémon's Attack is doubled in battle. This bonus does not count as a stat modifier. This ability functions identically to Huge Power.", species = 3, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_multiplier", stat = "attack", factor = 2 } } }, expressible = true },
  { id = "SHELLARMOR", n = 75, slug = "shell-armor", name = "Shell Armor", generation = 3, shortEffect = "Protects against critical hits.", effect = "Moves cannot score critical hits against this Pokémon. This ability functions identically to Battle Armor.", species = 32, expressible = false },
  { id = "AIRLOCK", n = 76, slug = "air-lock", name = "Air Lock", generation = 3, shortEffect = "Negates all effects of weather, but does not prevent the weather itself.", effect = "While this Pokémon is in battle, weather can still be in play, but will not have any of its effects. This ability functions identically to Cloud Nine.", species = 1, expressible = false },
  { id = "TANGLEDFEET", n = 77, slug = "tangled-feet", name = "Tangled Feet", generation = 4, shortEffect = "Doubles evasion when confused.", effect = "When this Pokémon is confused, it has twice its evasion.", species = 9, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_multiplier", stat = "evasion", factor = 2 } } }, expressible = false, notes = "while confused" },
  { id = "MOTORDRIVE", n = 78, slug = "motor-drive", name = "Motor Drive", generation = 4, shortEffect = "Absorbs Electric moves, raising Speed one stage.", effect = "Whenever an Electric-type move hits this Pokémon, its Speed rises one stage, negating any other effect on it. This ability will not take effect if this Pokémon is immune to Electric moves. Electric moves will ignore this Pokémon's Substitute. This effect includes non-damaging moves, i.e. Thunder Wave.", species = 4, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "type_immunity", moveType = "ELECTRIC" }, { kind = "stat_change", stat = "speed", stages = 1, when = "hit by an Electric-type move" } } }, expressible = true },
  { id = "RIVALRY", n = 79, slug = "rivalry", name = "Rivalry", generation = 4, shortEffect = "Increases damage inflicted to 1.25× against Pokémon of the same gender, but decreases damage to 0.75× against the opposite gender.", effect = "This Pokémon inflicts 1.25× as much regular damage against Pokémon of the same gender and 0.75× as much regular damage against Pokémon of the opposite gender. If either Pokémon is genderless, damage is unaffected.", species = 18, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.25, when = "same gender" }, { kind = "damage_dealt_multiplier", factor = 0.75, when = "opposite gender" } } }, expressible = true },
  { id = "STEADFAST", n = 80, slug = "steadfast", name = "Steadfast", generation = 4, shortEffect = "Raises Speed one stage upon flinching.", effect = "Whenever this Pokémon flinches, its Speed rises one stage.", species = 16, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_change", stat = "speed", stages = 1 } } }, expressible = false, notes = "when it flinches" },
  { id = "SNOWCLOAK", n = 81, slug = "snow-cloak", name = "Snow Cloak", generation = 4, shortEffect = "Increases evasion to 1.25× during hail. Protects against hail damage.", effect = "During hail, this Pokémon has 1.25× its evasion, and it does not take hail damage regardless of type. The evasion bonus does not count as a stat modifier. Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved in snow.", species = 15, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "stat_multiplier", stat = "evasion", factor = 1.25 } } }, expressible = false, notes = "in hail or snow" },
  { id = "GLUTTONY", n = 82, slug = "gluttony", name = "Gluttony", generation = 4, shortEffect = "Makes the Pokémon eat any held Berry triggered by low HP below 1/2 its max HP.", effect = "This Pokémon eats any held Berry triggered by low HP when it falls below 50% of its HP, regardless of the Berry's usual threshold.", species = 39, expressible = false },
  { id = "ANGERPOINT", n = 83, slug = "anger-point", name = "Anger Point", generation = 4, shortEffect = "Raises Attack to the maximum of six stages upon receiving a critical hit.", effect = "Whenever this Pokémon receives a critical hit, its Attack rises to the maximum of 6 stages. This ability will still take effect if the critical hit is received by a Substitute.", species = 12, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "stat_change", stat = "attack", stages = 12 } } }, expressible = false, notes = "after a critical hit" },
  { id = "UNBURDEN", n = 84, slug = "unburden", name = "Unburden", generation = 4, shortEffect = "Doubles Speed upon using or losing a held item.", effect = "When this Pokémon uses or loses its held item, its Speed is doubled. If it gains another item or leaves battle, this bonus is lost. This includes when the Pokémon drops its item because of Knock Off. This bonus does not count as a stat modifier. There is no notification when this ability takes effect.", species = 17, expressible = false },
  { id = "HEATPROOF", n = 85, slug = "heatproof", name = "Heatproof", generation = 4, shortEffect = "Halves damage from Fire moves and burns.", effect = "This Pokémon takes half as much damage from Fire-type moves and burns.", species = 5, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_taken_multiplier", factor = 0.5, moveType = "FIRE" } } }, expressible = false, notes = "also halves burn damage" },
  { id = "SIMPLE", n = 86, slug = "simple", name = "Simple", generation = 4, shortEffect = "Doubles the Pokémon's stat modifiers. These doubled modifiers are still capped at -6 or 6 stages.", effect = "Each stage of this Pokémon's stat modifiers acts as two stages. These doubled stages are still limited to a minimum of -6 and a maximum of 6. This Pokémon can still accumulate less than -3 or more than 3 stages of stat modifiers, even though the extra ones have no effect after doubling.", species = 5, expressible = false },
  { id = "DRYSKIN", n = 87, slug = "dry-skin", name = "Dry Skin", generation = 4, shortEffect = "Causes 1/8 max HP in damage each turn during strong sunlight, but heals for 1/8 max HP during rain. Increases damage from Fire moves to 1.25×, but absorbs Water moves, healing for 1/4 max HP.", effect = "This Pokémon takes 1/8 of its maximum HP in damage after each turn during strong sunlight, but it heals for 1/8 of its HP each turn during rain. This Pokémon takes 1.25× as much damage from Fire-type moves, but whenever a Water move hits it, it heals for 1/4 its maximum HP instead.", species = 7, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "type_immunity", moveType = "WATER" }, { kind = "heal", fraction = 0.25, when = "hit by a Water-type move" }, { kind = "heal", fraction = 0.125, when = "each turn in rain" }, { kind = "damage_self", fraction = 0.125, when = "each turn in harsh sunlight" } } }, expressible = false, notes = "also takes 1.25x from Fire moves" },
  { id = "DOWNLOAD", n = 88, slug = "download", name = "Download", generation = 4, shortEffect = "Raises the attack stat corresponding to the opponents' weaker defense one stage upon entering battle.", effect = "When this Pokémon enters battle, its Attack or Special Attack, whichever corresponds to its opponents' weaker total defensive stat, rises one stage. In the event of a tie, Special Attack is raised. This ability also takes effect when acquired during a battle.", species = 4, expressible = false },
  { id = "IRONFIST", n = 89, slug = "iron-fist", name = "Iron Fist", generation = 4, shortEffect = "Strengthens punch-based moves to 1.2× their power.", effect = "Moves flagged as being punch-based have 1.2× their base power for this Pokémon. Sucker Punch is not flagged as punch-based; its original, Japanese name only means \"surprise attack\".", species = 20, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.2 } } }, expressible = false, notes = "punching moves" },
  { id = "POISONHEAL", n = 90, slug = "poison-heal", name = "Poison Heal", generation = 4, shortEffect = "Heals for 1/8 max HP after each turn when poisoned in place of damage.", effect = "If this Pokémon is poisoned, it will heal for 1/8 of its maximum HP after each turn rather than taking damage. This includes bad poison.", species = 3, effectChanges = { { generation = 5, text = "If this Pokémon is poisoned, it will heal for 1/8 of its maximum HP after each turn rather than taking damage. This includes bad poison. This ability does not prevent poison damage while outside of a battle." } }, behaviour = { trigger = "turn_end", scope = "self", effects = { { kind = "heal", fraction = 0.125 } } }, expressible = false, notes = "while poisoned, instead of losing HP" },
  { id = "ADAPTABILITY", n = 91, slug = "adaptability", name = "Adaptability", generation = 4, shortEffect = "Increases the same-type attack bonus from 1.5× to 2×.", effect = "This Pokémon inflicts twice as much damage with moves whose types match its own, rather than the usual same-type attack bonus of 1.5×.", species = 20, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 2, when = "STAB" } } }, expressible = false, notes = "same-type bonus is 2x instead of 1.5x" },
  { id = "SKILLLINK", n = 92, slug = "skill-link", name = "Skill Link", generation = 4, shortEffect = "Extends two-to-five-hit moves and Triple Kick to their full length every time.", effect = "This Pokémon always hits five times with two-to-five-hit moves, such as Icicle Spear. It also bypasses the accuracy checks on Triple Kick's second and third hits.", species = 10, effectChanges = { { generation = 5, text = "This Pokémon always hits five times with two-to-five-hit moves, such as Icicle Spear." } }, expressible = false },
  { id = "HYDRATION", n = 93, slug = "hydration", name = "Hydration", generation = 4, shortEffect = "Cures any major status ailment after each turn during rain.", effect = "This Pokémon is cured of any major status ailment after each turn during rain.", species = 23, behaviour = { trigger = "turn_end", scope = "self", effects = {  } }, expressible = false, notes = "cures its status at the end of each turn in rain" },
  { id = "SOLARPOWER", n = 94, slug = "solar-power", name = "Solar Power", generation = 4, shortEffect = "Increases Special Attack to 1.5× but costs 1/8 max HP after each turn during strong sunlight.", effect = "During strong sunlight, this Pokémon has 1.5× its Special Attack but takes 1/8 of its maximum HP in damage after each turn.", species = 10, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "stat_multiplier", stat = "special-attack", factor = 1.5 }, { kind = "damage_self", fraction = 0.125, when = "each turn in harsh sunlight" } } }, expressible = false, notes = "in harsh sunlight" },
  { id = "QUICKFEET", n = 95, slug = "quick-feet", name = "Quick Feet", generation = 4, shortEffect = "Increases Speed to 1.5× with a major status ailment.", effect = "Whenever this Pokémon has a major status ailment, it has 1.5× its Speed. This Pokémon is not affected by the usual Speed cut from paralysis. Overworld: If the lead Pokémon has this ability, the wild encounter rate is halved.", species = 11, behaviour = { trigger = "on_status", scope = "self", effects = { { kind = "stat_multiplier", stat = "speed", factor = 1.5 } } }, expressible = false, notes = "with a status condition" },
  { id = "NORMALIZE", n = 96, slug = "normalize", name = "Normalize", generation = 4, shortEffect = "Makes the Pokémon's moves all act Normal-type.", effect = "This Pokémon's moves all act as if they were Normal-type. Moves that inflict typeless damage do so as usual. Moves of variable type, such as Hidden Power, are affected. They otherwise work as usual, however; Weather Ball, for example, is always forced to be Normal, but it still has doubled power and looks different during weather. As Thunder Wave is prevented by immunities, unlike most non-damaging moves, it does not affect Ghost-type Pokémon under the effect of this ability.", species = 2, expressible = false },
  { id = "SNIPER", n = 97, slug = "sniper", name = "Sniper", generation = 4, shortEffect = "Strengthens critical hits to inflict 3× damage rather than 2×.", effect = "This Pokémon inflicts triple damage with critical hits, rather than the usual double damage.", species = 18, expressible = false },
  { id = "MAGICGUARD", n = 98, slug = "magic-guard", name = "Magic Guard", generation = 4, shortEffect = "Protects against damage not directly caused by a move.", effect = "This Pokémon is immune to damage not directly caused by a move. For example, this Pokémon takes no damage from from weather, recoil, status ailments, or Spikes, but it still suffers from the Attack cut when burned, and a Life Orb will still power up this Pokémon's moves without damaging it. Anything that directly depends on such damage will also not happen; for example, Leech Seed will neither hurt this Pokémon nor heal the opponent, and Pokémon with a Jaboca Berry or Rowap Berry will not consume the berry when hit by this Pokémon. The following are unaffected: Struggle, Pain Split (whether used by or against this Pokémon), Belly Drum, Substitute, Curse, moves that knock the user out, and damage from confusion. This Pokémon will neither lose nor regain HP if it drains HP from a Pokémon with Liquid Ooze. If this Pokémon is badly poisoned, the poison counter is still increased each turn; if the Pokémon loses this ability, it will begin taking as much damage as it would be if it had been taking increasing damage each turn.", species = 10, effectChanges = { { generation = 5, text = "This Pokémon is immune to damage not directly caused by a move. For example, this Pokémon takes no damage from from weather, recoil, status ailments, or Spikes, but it still suffers from the Attack cut when burned, and a Life Orb will still power up this Pokémon's moves without damaging it. Anything that directly depends on such damage will also not happen; for example, Leech Seed will neither hurt this Pokémon nor heal the opponent, and Pokémon with a Jaboca Berry or Rowap Berry will not consume the berry when hit by this Pokémon. The following are unaffected: Struggle, Pain Split (whether used by or against this Pokémon), Belly Drum, Substitute, Curse, moves that knock the user out, and damage from confusion. This Pokémon will neither lose nor regain HP if it drains HP from a Pokémon with Liquid Ooze. If this Pokémon is badly poisoned, the poison counter is still increased each turn; if the Pokémon loses this ability, it will begin taking as much damage as it would be if it had been taking increasing damage each turn. Paralysis cannot prevent the Pokémon from moving, though the Speed cut is unaffected. Poison still damages the Pokémon outside of battle." } }, expressible = false },
  { id = "NOGUARD", n = 99, slug = "no-guard", name = "No Guard", generation = 4, shortEffect = "Ensures all moves used by and against the Pokémon hit.", effect = "Moves used by or against this Pokémon never miss. One-hit KO moves are unaffected. Moves affected by this ability can hit Pokémon during the preparation turn of moves like Dig or Fly. Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled.", species = 13, effectChanges = { { generation = 4, text = "Moves used by or against this Pokémon never miss. One-hit KO moves are unaffected. Moves affected by this ability can hit Pokémon during the preparation turn of moves like Dig or Fly. Due to a glitch, moves affected by this ability have a (100 - accuracy)% chance to hit through Detect or Protect. Overworld: If the lead Pokémon has this ability, the wild encounter rate is doubled." } }, expressible = false },
  { id = "STALL", n = 100, slug = "stall", name = "Stall", generation = 4, shortEffect = "Makes the Pokémon move last within its move's priority bracket.", effect = "This Pokémon moves last within its priority bracket. Multiple Pokémon with this ability move in order of Speed amongst themselves. The Full Incense and Lagging Tail take precedence over this ability; that is, Pokémon with these items move after Pokémon with this ability. Pokémon with both this ability and one of these items are delayed as much as if they had only the item. This ability works as usual during Trick Room: Pokémon with this ability will move in reverse order of Speed after Pokémon without it.", species = 1, expressible = false },
  { id = "TECHNICIAN", n = 101, slug = "technician", name = "Technician", generation = 4, shortEffect = "Strengthens moves of 60 base power or less to 1.5× their power.", effect = "This Pokémon's moves have 1.5× their power if their base power is 60 or less. This includes moves of variable power, such as Hidden Power and Magnitude, when their power is 60 or less. Helping Hand's power boost is taken into account for any move, as is Defense Curl's power boost for Rollout.", species = 28, effectChanges = { { generation = 5, text = "This Pokémon's moves have 1.5× their power if their base power is 60 or less. This includes moves of variable power, such as Hidden Power and Magnitude, when their power is 60 or less. Struggle is unaffected. Helping Hand and Defense Curls boost to Rollout are not taken into account." } }, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.5 } } }, expressible = false, notes = "moves of 60 power or less" },
  { id = "LEAFGUARD", n = 102, slug = "leaf-guard", name = "Leaf Guard", generation = 4, shortEffect = "Protects against major status ailments during strong sunlight.", effect = "This Pokémon cannot be given a major status ailment during strong sunlight. This ability does not heal prior status ailments. Rest will fail altogether with this ability in effect. Yawn will immediately fail if used on this Pokémon during strong sunlight, and an already-used Yawn will fail if the weather turns to strong sunlight in the meantime.", species = 23, effectChanges = { { generation = 5, text = "This Pokémon cannot be given a major status ailment during strong sunlight. This ability does not heal prior status ailments. Rest works as usual during strong sunlight. Yawn will immediately fail if used on this Pokémon during strong sunlight, and an already-used Yawn will fail if the weather turns to strong sunlight in the meantime." } }, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "status_immunity", status = "major" } } }, expressible = false, notes = "in harsh sunlight" },
  { id = "KLUTZ", n = 103, slug = "klutz", name = "Klutz", generation = 4, shortEffect = "Prevents the Pokémon from using its held item in battle.", effect = "In battle, this Pokémon cannot use its held item, nor will the item have any passive effect on the battle, positive or negative. This Pokémon also cannot use Fling. The Speed cut from the Iron Ball and the effort items (the Macho Brace, Power Weight, Power Bracer, Power Belt, Power Lens, Power Band, and Power Anklet) is unaffected. Items that do not directly affect the battle, such as the Exp. Share, the Amulet Coin, or the Soothe Bell, work as usual. All held items work as usual out of battle. Other moves that use the held item, such as Natural Gift and Switcheroo, work as usual.", species = 12, effectChanges = { { generation = 5, text = "In battle, this Pokémon cannot use its held item, nor will the item have any passive effect on the battle, positive or negative. The Speed cut from the Iron Ball and the effort items (the Macho Brace, Power Weight, Power Bracer, Power Belt, Power Lens, Power Band, and Power Anklet) is unaffected. Items that do not directly affect the battle, such as the Exp. Share, the Amulet Coin, or the Soothe Bell, work as usual. All held items work as usual out of battle. Other moves that use the held item, such as Natural Gift and Switcheroo, work as usual." } }, expressible = false },
  { id = "MOLDBREAKER", n = 104, slug = "mold-breaker", name = "Mold Breaker", generation = 4, shortEffect = "Bypasses targets' abilities if they could hinder or prevent a move.", effect = "This Pokémon's moves completely ignore abilities that could hinder or prevent their effect on the target. For example, this Pokémon's moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat. If an ability could either hinder or help this Pokémon's moves, e.g. Dry Skin or Unaware, the ability is ignored either way. Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected. For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move's effect on the user. This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle. This ability cannot ignore Multitype at all. An ability ignored by this ability is only nullified while the move is being used. For example, this Pokémon's moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon's Spikes are not affected by this ability after they have been placed. When this Pokémon enters battle, all participating trainers are notified that it has this ability. This ability functions identically to Teravolt and Turboblaze.", species = 27, expressible = false },
  { id = "SUPERLUCK", n = 105, slug = "super-luck", name = "Super Luck", generation = 4, shortEffect = "Raises moves' critical hit rates one stage.", effect = "This Pokémon's moves have critical hit rates one stage higher than normal.", species = 9, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "crit_change", amount = 1 } } }, expressible = true },
  { id = "AFTERMATH", n = 106, slug = "aftermath", name = "Aftermath", generation = 4, shortEffect = "Damages the attacker for 1/4 its max HP when knocked out by a contact move.", effect = "When this Pokémon is knocked out by a move that makes contact, the move's user takes 1/4 its maximum HP in damage.", species = 11, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "damage", fraction = 0.25 } } }, expressible = false, notes = "when knocked out by a contact move" },
  { id = "ANTICIPATION", n = 107, slug = "anticipation", name = "Anticipation", generation = 4, shortEffect = "Notifies all trainers upon entering battle if an opponent has a super-effective move, Self-Destruct, Explosion, or a one-hit KO move.", effect = "When this Pokémon enters battle, if one of its opponents has a move that is super effective against it, Self-Destruct, Explosion, or a one-hit knockout move, all participating trainers are notified. The move itself is not revealed; only that there is such a move. Moves that inflict typeless damage, such as Future Sight, and moves of variable type, such as Hidden Power, count as their listed types. Counter, Metal Burst, Mirror Coat, and one-hit KO moves to which this Pokémon is immune do not trigger this ability.", species = 18, expressible = false },
  { id = "FOREWARN", n = 108, slug = "forewarn", name = "Forewarn", generation = 4, shortEffect = "Reveals the opponents' strongest move upon entering battle.", effect = "When this Pokémon enters battle, it reveals the move with the highest base power known by any opposing Pokémon to all participating trainers. In the event of a tie, one is chosen at random. Moves without a listed base power are assigned one as follows: Power | Moves ----: | ----- 160 | One-hit KO moves: Fissure, Guillotine, Horn Drill, and Sheer Cold 120 | Counter moves: Counter, Metal Burst, and Mirror Coat 80 | Variable power or set damage: Crush Grip, Dragon Rage, Electro Ball, Endeavor, Final Gambit, Flail, Frustration, Grass Knot, Gyro Ball, Heat Crash, Heavy Slam, Hidden Power, Low Kick, Natural Gift, Night Shade, Psywave, Return, Reversal, Seismic Toss, Sonic Boom, Trump Card, and Wring Out 0 | Any such move not listed", species = 6, expressible = false },
  { id = "UNAWARE", n = 109, slug = "unaware", name = "Unaware", generation = 4, shortEffect = "Ignores other Pokémon's stat modifiers for damage and accuracy calculation.", effect = "This Pokémon ignores other Pokémon's stat modifiers for the purposes of damage and accuracy calculation. Effectively, this affects modifiers of every stat except Speed. The power of Punishment and Stored Power is calculated as usual. When this Pokémon hurts itself in confusion, its stat modifiers affect damage as usual.", species = 15, expressible = false },
  { id = "TINTEDLENS", n = 110, slug = "tinted-lens", name = "Tinted Lens", generation = 4, shortEffect = "Doubles damage inflicted with not-very-effective moves.", effect = "This Pokémon deals twice as much damage with moves that are not very effective against the target.", species = 13, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 2 } } }, expressible = false, notes = "not-very-effective hits" },
  { id = "FILTER", n = 111, slug = "filter", name = "Filter", generation = 4, shortEffect = "Decreases damage taken from super-effective moves by 1/4.", effect = "This Pokémon takes 0.75× as much damage from moves that are super effective against it. This ability functions identically to Solid Rock.", species = 4, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_taken_multiplier", factor = 0.75 } } }, expressible = false, notes = "super-effective hits" },
  { id = "SLOWSTART", n = 112, slug = "slow-start", name = "Slow Start", generation = 4, shortEffect = "Halves Attack and Speed for five turns upon entering battle.", effect = "This Pokémon's Attack and Speed are halved for five turns upon entering battle. This ability also takes effect when acquired during battle. If this Pokémon loses its ability before the five turns are up, its Attack and Speed return to normal; if it then regains this ability without leaving battle, its Attack and Speed are halved again, but the counter keeps counting from where it was.", species = 2, behaviour = { trigger = "switch_in", scope = "self", effects = { { kind = "stat_multiplier", stat = "attack", factor = 0.5 }, { kind = "stat_multiplier", stat = "speed", factor = 0.5 } } }, expressible = false, notes = "for five turns" },
  { id = "SCRAPPY", n = 113, slug = "scrappy", name = "Scrappy", generation = 4, shortEffect = "Lets the Pokémon's Normal and Fighting moves hit Ghost Pokémon.", effect = "This Pokémon ignores Ghost-type Pokémon's immunity to Normal- and Fighting-type moves. Ghost Pokémon's other types affect damage as usual.", species = 15, expressible = false },
  { id = "STORMDRAIN", n = 114, slug = "storm-drain", name = "Storm Drain", generation = 4, shortEffect = "Redirects single-target Water moves to this Pokémon where possible. Absorbs Water moves, raising Special Attack one stage.", effect = "All other Pokémon's single-target Water-type moves are redirected to this Pokémon, if it is an eligible target. Other Pokémon's Water moves raise this Pokémon's Special Attack one stage, negating any other effect on it, and cannot miss it. If the move's intended target also has this ability, the move is not redirected. When multiple Pokémon with this ability are possible targets for redirection, the move is redirected to the one with the highest Speed stat, or, in the case of a tie, to a random tied Pokémon. Follow Me takes precedence over this ability.", species = 10, effectChanges = { { generation = 5, text = "If this Pokemon is not the target of a single-target Water-type move used by another Pokemon, this Pokemon redirects that move to itself. This ability counts hidden power as normal type." } }, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "type_immunity", moveType = "WATER" }, { kind = "stat_change", stat = "special-attack", stages = 1, when = "hit by a Water-type move" } } }, expressible = false, notes = "also draws Water moves to itself" },
  { id = "ICEBODY", n = 115, slug = "ice-body", name = "Ice Body", generation = 4, shortEffect = "Heals for 1/16 max HP after each turn during hail. Protects against hail damage.", effect = "This Pokémon heals for 1/16 of its maximum HP after each turn during hail, and it does not take hail damage regardless of type.", species = 21, behaviour = { trigger = "turn_end", scope = "self", effects = { { kind = "heal", fraction = 0.0625, when = "each turn in snow" } } }, expressible = true },
  { id = "SOLIDROCK", n = 116, slug = "solid-rock", name = "Solid Rock", generation = 4, shortEffect = "Decreases damage taken from super-effective moves by 1/4.", effect = "This Pokémon takes 0.75× as much damage from moves that are super effective against it. This ability functions identically to Filter.", species = 4, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_taken_multiplier", factor = 0.75 } } }, expressible = false, notes = "super-effective hits" },
  { id = "SNOWWARNING", n = 117, slug = "snow-warning", name = "Snow Warning", generation = 4, shortEffect = "Summons hail that lasts indefinitely upon entering battle.", effect = "The weather changes to hail when this Pokémon enters battle and does not end unless cancelled by another weather condition. If multiple Pokémon with this ability, Drizzle, Drought, or Sand Stream are sent out at the same time, the abilities will activate in order of Speed, respecting Trick Room. Each ability's weather will cancel the previous weather, and only the weather summoned by the slowest of the Pokémon will stay.", species = 9, behaviour = { trigger = "switch_in", scope = "field", effects = { { kind = "set_weather", weather = "hail" } } }, expressible = true },
  { id = "HONEYGATHER", n = 118, slug = "honey-gather", name = "Honey Gather", generation = 4, shortEffect = "The Pokémon may pick up Honey after battle.", effect = "This Pokémon has a chance of picking up Honey after each battle. This chance starts at 5% and rises another 5% after every tenth level: 5% from level 1–10, 10% from 11–20, and so on, up to 50% from 91–100. This ability is checked after the battle ends, at which point any temporary ability changes have worn off.", species = 5, expressible = false },
  { id = "FRISK", n = 119, slug = "frisk", name = "Frisk", generation = 4, shortEffect = "Reveals an opponent's held item upon entering battle.", effect = "When this Pokémon enters battle, it reveals an opposing Pokémon's held item to all participating trainers. In a double battle, if one opponent has an item, this Pokémon will Frisk that Pokémon; if both have an item, it will Frisk one at random.", species = 38, expressible = false },
  { id = "RECKLESS", n = 120, slug = "reckless", name = "Reckless", generation = 4, shortEffect = "Strengthens recoil moves to 1.2× their power.", effect = "This Pokémon's recoil moves and crash moves have 1.2× their base power. Struggle is unaffected. The \"crash moves\" are the moves that damage the user upon missing: Jump Kick and High Jump Kick.", species = 13, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.2 } } }, expressible = false, notes = "moves with recoil or crash damage" },
  { id = "MULTITYPE", n = 121, slug = "multitype", name = "Multitype", generation = 4, shortEffect = "Changes Arceus's type and form to match its held Plate.", effect = "If this Pokémon is holding an elemental Plate, its type and form change to match the Plate. This Pokémon's held item, whether or not it is a Plate, cannot be taken by Covet or Thief, nor removed by Knock Off, nor traded by Switcheroo or Trick. Covet, Thief, and Knock Off still inflict damage against this Pokémon. Unlike with Sticky Hold, this Pokémon cannot use Fling, Switcheroo, or Trick to lose its item itself, nor gain an item through Switcheroo or Trick if it does not have one. This ability has no effect for any Pokémon other than Arceus. This ability cannot be traded with Skill Swap, nor copied with Role Play or Trace, nor disabled with Gastro Acid, nor changed with Worry Seed. This Pokémon cannot use Skill Swap or Role Play to lose its ability itself. Mold Breaker cannot ignore this ability. If a Pokémon Transforms into an Arceus with this ability, it will Transform into Arceus's default, Normal-type form. If the Transforming Pokémon is holding a Plate, this ability will then activate and change the Pokémon into the corresponding form.", species = 1, expressible = false },
  { id = "FLOWERGIFT", n = 122, slug = "flower-gift", name = "Flower Gift", generation = 4, shortEffect = "Increases friendly Pokémon's Attack and Special Defense to 1.5× during strong sunlight.", effect = "Friendly Pokémon have 1.5× their Attack and Special Defense during strong sunlight if any friendly Pokémon has this ability. Unlike Forecast, Multitype, and Zen Mode, this ability is not tied to its Pokémon's form change; Cherrim will switch between its forms even if it loses this ability. As such, this ability also works if obtained by a Pokémon other than Cherrim.", species = 1, expressible = false },
  { id = "BADDREAMS", n = 123, slug = "bad-dreams", name = "Bad Dreams", generation = 4, shortEffect = "Damages sleeping opponents for 1/8 their max HP after each turn.", effect = "Opposing Pokémon take 1/8 of their maximum HP in damage after each turn while they are asleep.", species = 1, expressible = false },
  { id = "PICKPOCKET", n = 124, slug = "pickpocket", name = "Pickpocket", generation = 5, shortEffect = "Steals attacking Pokémon's held items on contact.", effect = "Whenever a move makes contact with this Pokémon, if it does not have a held item, it steals the attacker's held item. This Pokémon cannot steal upon being knocked out. It can steal if the attacker has a Substitute, but cannot steal when its own Substitute is hit. If a move hits multiple times, only the last hit triggers this ability. If this Pokémon is wild, it cannot steal from a trained Pokémon.", species = 16, expressible = false },
  { id = "SHEERFORCE", n = 125, slug = "sheer-force", name = "Sheer Force", generation = 5, shortEffect = "Strengthens moves with extra effects to 1.3× their power, but prevents their extra effects.", effect = "This Pokémon's moves with extra effects have 1.3× their power, but lose their extra effects. An effect chance is a move's chance to inflict a status ailment, cause a stat change, or make the target flinch in addition to the move's main effect. For example, Thunder Shock's paralysis is an extra effect, but Thunder Wave's is not, nor are Knock Off's item removal and Air Cutter's increased critical hit rate. Moves that lower the user's stats are unaffected.", species = 37, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.3 } } }, expressible = false, notes = "moves with added effects, which it removes" },
  { id = "CONTRARY", n = 126, slug = "contrary", name = "Contrary", generation = 5, shortEffect = "Inverts stat changes.", effect = "Whenever this Pokémon's stats would be raised, they are instead lowered by the same amount, and vice versa.", species = 13, expressible = false },
  { id = "UNNERVE", n = 127, slug = "unnerve", name = "Unnerve", generation = 5, shortEffect = "Prevents opposing Pokémon from eating held Berries.", effect = "Opposing Pokémon cannot eat held Berries while this Pokémon is in battle. Affected Pokémon can still use Bug Bite or Pluck to eat a target's Berry.", species = 28, expressible = false },
  { id = "DEFIANT", n = 128, slug = "defiant", name = "Defiant", generation = 5, shortEffect = "Raises Attack two stages upon having any stat lowered.", effect = "When any of this Pokémon's stats are lowered, its Attack rises by two stages. If multiple stats are lowered at once, this ability takes effect with each stat lowered.", species = 17, expressible = false },
  { id = "DEFEATIST", n = 129, slug = "defeatist", name = "Defeatist", generation = 5, shortEffect = "Halves Attack and Special Attack at 50% max HP or less.", effect = "This Pokémon's Attack and Special Attack are halved when it has half its HP or less.", species = 2, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_multiplier", stat = "attack", factor = 0.5 }, { kind = "stat_multiplier", stat = "special-attack", factor = 0.5 } } }, expressible = false, notes = "at half HP or less" },
  { id = "CURSEDBODY", n = 130, slug = "cursed-body", name = "Cursed Body", generation = 5, shortEffect = "Has a 30% chance of Disabling any move that hits the Pokémon.", effect = "Moves that hit this Pokémon have a 30% chance of being Disabled afterward.", species = 15, expressible = false },
  { id = "HEALER", n = 131, slug = "healer", name = "Healer", generation = 5, shortEffect = "Has a 30% chance of curing each adjacent ally of any major status ailment after each turn.", effect = "Friendly Pokémon next to this Pokémon in double and triple battles each have a 30% chance of being cured of any major status ailment after each turn.", species = 12, behaviour = { trigger = "turn_end", scope = "allies", effects = {  }, chance = 30 }, expressible = true },
  { id = "FRIENDGUARD", n = 132, slug = "friend-guard", name = "Friend Guard", generation = 5, shortEffect = "Decreases all direct damage taken by friendly Pokémon to 0.75×.", effect = "All friendly Pokémon take 0.75× as much direct damage from moves while this Pokémon is in battle. This effect stacks if multiple allied Pokémon have it.", species = 10, behaviour = { trigger = "passive", scope = "allies", effects = { { kind = "damage_taken_multiplier", factor = 0.75 } } }, expressible = true },
  { id = "WEAKARMOR", n = 133, slug = "weak-armor", name = "Weak Armor", generation = 5, shortEffect = "Raises Speed and lowers Defense by one stage each upon being hit by a physical move.", effect = "Whenever a physical move hits this Pokémon, its Speed rises one stage and its Defense falls one stage. This ability triggers on every hit of a multiple-hit move.", species = 25, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "stat_change", stat = "defense", stages = -1 }, { kind = "stat_change", stat = "speed", stages = 2 } } }, expressible = false, notes = "when hit by a physical move" },
  { id = "HEAVYMETAL", n = 134, slug = "heavy-metal", name = "Heavy Metal", generation = 5, shortEffect = "Doubles the Pokémon's weight.", effect = "This Pokémon has double the usual weight for its species.", species = 10, expressible = false },
  { id = "LIGHTMETAL", n = 135, slug = "light-metal", name = "Light Metal", generation = 5, shortEffect = "Halves the Pokémon's weight.", effect = "This Pokémon has half the usual weight for its species.", species = 7, expressible = false },
  { id = "MULTISCALE", n = 136, slug = "multiscale", name = "Multiscale", generation = 5, shortEffect = "Halves damage taken from full HP.", effect = "This Pokémon takes half as much damage when it is hit having full HP.", species = 3, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_taken_multiplier", factor = 0.5 } } }, expressible = false, notes = "at full HP" },
  { id = "TOXICBOOST", n = 137, slug = "toxic-boost", name = "Toxic Boost", generation = 5, shortEffect = "Increases Attack to 1.5× when poisoned.", effect = "This Pokémon has 1.5× its Attack when poisoned.", species = 1, behaviour = { trigger = "on_status", scope = "self", effects = { { kind = "stat_multiplier", stat = "attack", factor = 1.5 } } }, expressible = false, notes = "while poisoned" },
  { id = "FLAREBOOST", n = 138, slug = "flare-boost", name = "Flare Boost", generation = 5, shortEffect = "Increases Special Attack to 1.5× when burned.", effect = "This Pokémon has 1.5× its Special Attack when burned.", species = 2, behaviour = { trigger = "on_status", scope = "self", effects = { { kind = "stat_multiplier", stat = "special-attack", factor = 1.5 } } }, expressible = false, notes = "while burned" },
  { id = "HARVEST", n = 139, slug = "harvest", name = "Harvest", generation = 5, shortEffect = "Has a 50% chance of restoring a used Berry after each turn if the Pokémon has held no items in the meantime.", effect = "After each turn, if the last item this Pokémon consumed was a Berry and it is not currently holding an item, it has a 50% chance of regaining that Berry, or a 100% chance during strong sunlight.", species = 9, expressible = false },
  { id = "TELEPATHY", n = 140, slug = "telepathy", name = "Telepathy", generation = 5, shortEffect = "Protects against friendly Pokémon's damaging moves.", effect = "This Pokémon does not take damage from friendly Pokémon's moves, including single-target moves aimed at it.", species = 28, expressible = false },
  { id = "MOODY", n = 141, slug = "moody", name = "Moody", generation = 5, shortEffect = "Raises a random stat two stages and lowers another one stage after each turn.", effect = "After each turn, one of this Pokémon's stats at random rises two stages, and another falls one stage. If a stat is already at 6 or -6 stages, it will not be chosen to be increased or decreased, respectively.", species = 8, expressible = false },
  { id = "OVERCOAT", n = 142, slug = "overcoat", name = "Overcoat", generation = 5, shortEffect = "Protects against damage from weather.", effect = "This Pokémon does not take damage from weather.", species = 26, expressible = false },
  { id = "POISONTOUCH", n = 143, slug = "poison-touch", name = "Poison Touch", generation = 5, shortEffect = "Has a 30% chance of poisoning target Pokémon upon contact.", effect = "This Pokémon's contact moves have a 30% chance of poisoning the target with each hit. This counts as an extra effect for the purposes of Shield Dust. This ability takes effect before Mummy.", species = 11, behaviour = { trigger = "passive", scope = "foes", effects = { { kind = "inflict_status", status = "poison" } }, chance = 30 }, expressible = false, notes = "on its own contact moves" },
  { id = "REGENERATOR", n = 144, slug = "regenerator", name = "Regenerator", generation = 5, shortEffect = "Heals for 1/3 max HP upon switching out.", effect = "This Pokémon regains 1/3 of its maximum HP when it is switched out for another Pokémon under any circumstances other than having fainted. This ability does not take effect when a battle ends.", species = 28, behaviour = { trigger = "on_switch_out", scope = "self", effects = { { kind = "heal", fraction = 0.3333 } } }, expressible = true },
  { id = "BIGPECKS", n = 145, slug = "big-pecks", name = "Big Pecks", generation = 5, shortEffect = "Protects against Defense drops.", effect = "This Pokémon's Defense cannot be lowered by other Pokémon. This Pokémon can still be passed negative Defense modifiers through Heart Swap or Guard Swap.", species = 15, expressible = false },
  { id = "SANDRUSH", n = 146, slug = "sand-rush", name = "Sand Rush", generation = 5, shortEffect = "Doubles Speed during a sandstorm. Protects against sandstorm damage.", effect = "This Pokémon's Speed is doubled during a sandstorm, and it does not take sandstorm damage, regardless of type.", species = 10, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "stat_multiplier", stat = "speed", factor = 2 } } }, expressible = false, notes = "in a sandstorm" },
  { id = "WONDERSKIN", n = 147, slug = "wonder-skin", name = "Wonder Skin", generation = 5, shortEffect = "Lowers incoming non-damaging moves' base accuracy to exactly 50%.", effect = "Non-damaging moves have exactly 50% base accuracy against this Pokémon.", species = 5, expressible = false },
  { id = "ANALYTIC", n = 148, slug = "analytic", name = "Analytic", generation = 5, shortEffect = "Strengthens moves to 1.3× their power when moving last.", effect = "This Pokémon's moves have 1.3× their power when it moves last in a turn. Future Sight and Doom Desire are unaffected.", species = 12, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.3 } } }, expressible = false, notes = "when moving last" },
  { id = "ILLUSION", n = 149, slug = "illusion", name = "Illusion", generation = 5, shortEffect = "Takes the appearance of the last conscious party Pokémon upon being sent out until hit by a damaging move.", effect = "This Pokémon, upon being sent out, appears to have the species, nickname, and Poké Ball of the last Pokémon in the party that is able to battle. This illusion breaks upon being hit by a damaging move. Other damage, e.g. from weather or Spikes, does not break the illusion, nor does damage done to a Substitute. If the party order becomes temporarily shuffled around as Pokémon are switched out in battle, this ability chooses the last Pokémon according to that shuffled order.", species = 4, expressible = false },
  { id = "IMPOSTER", n = 150, slug = "imposter", name = "Imposter", generation = 5, shortEffect = "Transforms upon entering battle.", effect = "This Pokémon transforms into a random opponent upon entering battle. This effect is identical to the move Transform.", species = 1, expressible = false },
  { id = "INFILTRATOR", n = 151, slug = "infiltrator", name = "Infiltrator", generation = 5, shortEffect = "Bypasses Light Screen, Reflect, and Safeguard.", effect = "This Pokémon's moves ignore Light Screen, Reflect, and Safeguard.", species = 27, expressible = false },
  { id = "MUMMY", n = 152, slug = "mummy", name = "Mummy", generation = 5, shortEffect = "Changes attacking Pokémon's abilities to Mummy on contact.", effect = "Whenever a contact move hits this Pokémon, the attacking Pokémon's ability changes to Mummy. Multitype is unaffected. If a Pokémon with Moxie knocks this Pokémon out, the former's ability will change without taking effect.", species = 2, expressible = false },
  { id = "MOXIE", n = 153, slug = "moxie", name = "Moxie", generation = 5, shortEffect = "Raises Attack one stage upon KOing a Pokémon.", effect = "This Pokémon's Attack rises one stage upon knocking out another Pokémon, even a friendly Pokémon. This ability does not take effect when the Pokémon indirectly causes another Pokémon to faint, e.g. through poison or Spikes. If this Pokémon knocks out a Pokémon with Mummy, the former's ability will change without taking effect.", species = 16, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "stat_change", stat = "attack", stages = 1 } } }, expressible = false, notes = "after knocking out a Pokemon" },
  { id = "JUSTIFIED", n = 154, slug = "justified", name = "Justified", generation = 5, shortEffect = "Raises Attack one stage upon taking damage from a Dark move.", effect = "Whenever a Dark-type move hits this Pokémon, its Attack rises one stage. The move is not negated in any way.", species = 10, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "stat_change", stat = "attack", stages = 1, when = "hit by a Dark-type move" } } }, expressible = true },
  { id = "RATTLED", n = 155, slug = "rattled", name = "Rattled", generation = 5, shortEffect = "Raises Speed one stage upon being hit by a Dark, Ghost, or Bug move.", effect = "This Pokémon's Speed rises one stage with each hit from a damaging Dark-, Ghost-, or Bug-type move.", species = 21, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "stat_change", stat = "speed", stages = 1, when = "hit by a Bug-, Ghost- or Dark-type move" } } }, expressible = true },
  { id = "MAGICBOUNCE", n = 156, slug = "magic-bounce", name = "Magic Bounce", generation = 5, shortEffect = "Reflects most non-damaging moves back at their user.", effect = "When this Pokémon is targeted by a move flagged as being reflectable, the move is redirected to its user. All reflectable moves are non-damaging, and most non-damaging moves that target other Pokémon are reflectable. A move reflected by this ability or Magic Coat cannot be reflected back.", species = 11, expressible = false },
  { id = "SAPSIPPER", n = 157, slug = "sap-sipper", name = "Sap Sipper", generation = 5, shortEffect = "Absorbs Grass moves, raising Attack one stage.", effect = "Whenever a Grass-type move hits this Pokémon, its Attack rises one stage, negating any other effect on it.", species = 21, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "type_immunity", moveType = "GRASS" }, { kind = "stat_change", stat = "attack", stages = 1, when = "hit by a Grass-type move" } } }, expressible = true },
  { id = "PRANKSTER", n = 158, slug = "prankster", name = "Prankster", generation = 5, shortEffect = "Raises non-damaging moves' priority by one stage.", effect = "This Pokémon's non-damaging moves have their priority increased by one stage.", species = 20, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "priority_change", amount = 1 } } }, expressible = false, notes = "status moves" },
  { id = "SANDFORCE", n = 159, slug = "sand-force", name = "Sand Force", generation = 5, shortEffect = "Strengthens Rock, Ground, and Steel moves to 1.3× their power during a sandstorm. Protects against sandstorm damage.", effect = "During a sandstorm, this Pokémon's Rock-, Ground-, and Steel-type moves have 1.3× their base power. This Pokémon does not take sandstorm damage, regardless of type.", species = 18, behaviour = { trigger = "on_weather", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.3, moveType = "ROCK" }, { kind = "damage_dealt_multiplier", factor = 1.3, moveType = "GROUND" }, { kind = "damage_dealt_multiplier", factor = 1.3, moveType = "STEEL" } } }, expressible = false, notes = "in a sandstorm; also immune to sandstorm damage" },
  { id = "IRONBARBS", n = 160, slug = "iron-barbs", name = "Iron Barbs", generation = 5, shortEffect = "Damages attacking Pokémon for 1/8 their max HP on contact.", effect = "Whenever a move makes contact with this Pokémon, the move's user takes 1/8 of its maximum HP in damage. This ability functions identically to Rough Skin.", species = 4, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "damage", fraction = 0.125 } } }, expressible = true },
  { id = "ZENMODE", n = 161, slug = "zen-mode", name = "Zen Mode", generation = 5, shortEffect = "Changes Darmanitan's form after each turn depending on its HP: Zen Mode below 50% max HP, and Standard Mode otherwise.", effect = "This Pokémon switches between Standard Mode and Zen Mode after each turn depending on its HP. Below 50% of its maximum HP, it switches to Zen Mode, and at 50% or above, it switches to Standard Mode. This Pokémon returns to Standard Mode upon leaving battle or losing this ability. This ability has no effect if this Pokémon is not a Darmanitan.", species = 4, expressible = false },
  { id = "VICTORYSTAR", n = 162, slug = "victory-star", name = "Victory Star", generation = 5, shortEffect = "Increases moves' accuracy to 1.1× for friendly Pokémon.", effect = "All friendly Pokémon's moves, including this Pokémon's own moves, have 1.1× their usual accuracy while this Pokémon is in battle.", species = 1, behaviour = { trigger = "passive", scope = "allies", effects = { { kind = "accuracy_multiplier", factor = 1.1 } } }, expressible = true },
  { id = "TURBOBLAZE", n = 163, slug = "turboblaze", name = "Turboblaze", generation = 5, shortEffect = "Bypasses targets' abilities if they could hinder or prevent moves.", effect = "This Pokémon's moves completely ignore abilities that could hinder or prevent their effect on the target. For example, this Pokémon's moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat. If an ability could either hinder or help this Pokémon's moves, e.g. Dry Skin or Unaware, the ability is ignored either way. Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected. For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move's effect on the user. This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle. This ability cannot ignore Multitype at all. An ability ignored by this ability is only nullified while the move is being used. For example, this Pokémon's moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon's Spikes are not affected by this ability after they have been placed. When this Pokémon enters battle, all participating trainers are notified that it has this ability. This ability functions identically to Mold Breaker and Teravolt.", species = 2, expressible = false },
  { id = "TERAVOLT", n = 164, slug = "teravolt", name = "Teravolt", generation = 5, shortEffect = "Bypasses targets' abilities if they could hinder or prevent moves.", effect = "This Pokémon's moves completely ignore abilities that could hinder or prevent their effect on the target. For example, this Pokémon's moves ignore abilities that would fully negate them, such as Water Absorb; abilities that would prevent any of their effects, such as Clear Body, Shell Armor, or Sticky Hold; and abilities that grant any general protective benefit, such as Simple, Snow Cloak, or Thick Fat. If an ability could either hinder or help this Pokémon's moves, e.g. Dry Skin or Unaware, the ability is ignored either way. Abilities that do not fit this description, even if they could hinder moves in some other way, are not affected. For example, Cursed Body only affects potential future uses of the move, while Liquid Ooze and Shadow Tag can only hinder a move's effect on the user. This ablity cannot ignore type or form changes granted by abilities, for example Color Change or Forecast; nor effects that were caused by abilities but are no longer tied to an ability, such as the rain from Drizzle. This ability cannot ignore Multitype at all. An ability ignored by this ability is only nullified while the move is being used. For example, this Pokémon's moves can paralyze a Pokémon with Limber, but Limber will activate and heal the paralysis immediately thereafter, and this Pokémon's Spikes are not affected by this ability after they have been placed. When this Pokémon enters battle, all participating trainers are notified that it has this ability. This ability functions identically to Mold Breaker and Turboblaze.", species = 2, expressible = false },
  { id = "AROMAVEIL", n = 165, slug = "aroma-veil", name = "Aroma Veil", generation = 6, shortEffect = "Protects allies against moves that affect their mental state.", effect = "Protects allies against moves that affect their mental state.", species = 8, expressible = false },
