  { id = "STRONGJAW", n = 173, slug = "strong-jaw", name = "Strong Jaw", generation = 6, shortEffect = "Strengthens biting moves to 1.5× their power.", effect = "Strengthens biting moves to 1.5× their power.", species = 13, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.5 } } }, expressible = false, notes = "biting moves" },
