  { id = "GALEWINGS", n = 177, slug = "gale-wings", name = "Gale Wings", generation = 6, shortEffect = "Raises Flying moves' priority by one stage.", effect = "Raises Flying moves' priority by one stage.", species = 3, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "priority_change", amount = 1 } } }, expressible = false, notes = "Flying moves at full HP" },
