  { id = "SYMBIOSIS", n = 180, slug = "symbiosis", name = "Symbiosis", generation = 6, shortEffect = "Passes the bearer's held item to an ally when the ally uses up its item.", effect = "Passes the bearer's held item to an ally when the ally uses up its item.", species = 5, expressible = false },
  { id = "TOUGHCLAWS", n = 181, slug = "tough-claws", name = "Tough Claws", generation = 6, shortEffect = "Strengthens moves that make contact to 1.33× their power.", effect = "Strengthens moves that make contact to 1.33× their power.", species = 10, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 1.3 } } }, expressible = false, notes = "contact moves" },
  { id = "PIXILATE", n = 182, slug = "pixilate", name = "Pixilate", generation = 6, shortEffect = "Turns the bearer's Normal moves into Fairy moves and strengthens them to 1.3× their power.", effect = "Turns the bearer's Normal-type moves into Fairy moves. Moves changed by this ability have 1.3× their power.", species = 3, expressible = false },
  { id = "GOOEY", n = 183, slug = "gooey", name = "Gooey", generation = 6, shortEffect = "Lowers attacking Pokémon's Speed by one stage on contact.", effect = "Lowers attacking Pokémon's Speed by one stage on contact.", species = 7, behaviour = { trigger = "on_contact_taken", scope = "foes", effects = { { kind = "stat_change", stat = "speed", stages = -1 } } }, expressible = true },
  { id = "AERILATE", n = 184, slug = "aerilate", name = "Aerilate", generation = 6, shortEffect = "Turns the bearer's Normal moves into Flying moves and strengthens them to 1.3× their power.", effect = "Turns the bearer's Normal-type moves into Flying-type moves. Moves changed by this ability have 1.3× their power.", species = 2, expressible = false },
  { id = "PARENTALBOND", n = 185, slug = "parental-bond", name = "Parental Bond", generation = 6, shortEffect = "Lets the bearer hit twice with damaging moves. The second hit has half power.", effect = "Lets the bearer hit twice with damaging moves. The second hit has half power.", species = 1, expressible = false },
  { id = "DARKAURA", n = 186, slug = "dark-aura", name = "Dark Aura", generation = 6, shortEffect = "Strengthens Dark moves to 1.33× their power for all friendly and opposing Pokémon.", effect = "Strengthens Dark moves for all friendly and opposing Pokémon.", species = 1, behaviour = { trigger = "passive", scope = "field", effects = { { kind = "damage_dealt_multiplier", factor = 1.3301, moveType = "DARK" } } }, expressible = true },
  { id = "FAIRYAURA", n = 187, slug = "fairy-aura", name = "Fairy Aura", generation = 6, shortEffect = "Strengthens Fairy moves to 1.33× their power for all friendly and opposing Pokémon.", effect = "Strengthens Fairy moves for all friendly and opposing Pokémon.", species = 2, behaviour = { trigger = "passive", scope = "field", effects = { { kind = "damage_dealt_multiplier", factor = 1.3301, moveType = "FAIRY" } } }, expressible = true },
  { id = "AURABREAK", n = 188, slug = "aura-break", name = "Aura Break", generation = 6, shortEffect = "Makes Dark Aura and Fairy Aura weaken moves of their respective types.", effect = "While this Pokémon is on the field, Dark Aura and Fairy Aura weaken moves of their respective types to 2/3 their power, rather than strengthening them.", species = 2, expressible = false },
  { id = "PRIMORDIALSEA", n = 189, slug = "primordial-sea", name = "Primordial Sea", generation = 6, shortEffect = "Creates heavy rain, which has all the properties of Rain Dance, cannot be replaced, and causes damaging Fire moves to fail.", effect = "When this Pokémon enters battle or gains this ability, the weather becomes heavy rain. Heavy rain has all the properties of Rain Dance and also causes damaging Fire moves to fail. Heavy rain ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified. The weather cannot otherwise be changed except by the effects of Delta Stream and Desolate Land. Air Lock and Cloud Nine will prevent the effects of heavy rain, including allowing Fire moves to work, but will not allow the weather to be changed.", species = 1, behaviour = { trigger = "switch_in", scope = "field", effects = { { kind = "set_weather", weather = "rain" } } }, expressible = false, notes = "heavy rain" },
  { id = "DESOLATELAND", n = 190, slug = "desolate-land", name = "Desolate Land", generation = 6, shortEffect = "Creates extremely harsh sunlight, which has all the properties of Sunny Day, cannot be replaced, and causes damaging Water moves to fail.", effect = "When this Pokémon enters battle or gains this ability, the weather becomes extremely harsh sunlight. Extremely harsh sunlight has all the properties of Sunny Day and also causes damaging Water moves to fail. Extremely harsh sunlight ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified. The weather cannot otherwise be changed except by the effects of Delta Stream and Primordial Sea. Air Lock and Cloud Nine will prevent the effects of extremely harsh sunlight, including allowing Water moves to work, but will not allow the weather to be changed.", species = 1, behaviour = { trigger = "switch_in", scope = "field", effects = { { kind = "set_weather", weather = "sun" } } }, expressible = false, notes = "extremely harsh sunlight" },
  { id = "DELTASTREAM", n = 191, slug = "delta-stream", name = "Delta Stream", generation = 6, shortEffect = "Creates a mysterious air current, which cannot be replaced and causes moves to never be super effective against Flying Pokémon.", effect = "When this Pokémon enters battle or gains this ability, the weather becomes a mysterious air current. A mysterious air current causes moves to not be super effective against Flying; they do neutral damage instead. Anticipation and Stealth Rock are not affected. The mysterious air current ends when this Pokémon leaves battle or loses this ability, or when this ability is nullified. The weather cannot otherwise be changed except by the effects of Desolate Land and Primordial Sea. Air Lock and Cloud Nine will prevent the effect of a mysterious air current, but will not allow the weather to be changed.", species = 1, expressible = false },
  { id = "STAMINA", n = 192, slug = "stamina", name = "Stamina", generation = 7, shortEffect = "Raises this Pokémon's Defense by one stage when it takes damage from a move.", effect = "Raises this Pokémon's Defense by one stage when it takes damage from a move.", species = 3, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "stat_change", stat = "defense", stages = 1, when = "hit by a damaging move" } } }, expressible = true },
  { id = "WIMPOUT", n = 193, slug = "wimp-out", name = "Wimp Out", generation = 7, shortEffect = "This Pokémon automatically switches out when its HP drops below half.", effect = "After this Pokémon is hit by a move, if that move caused this Pokémon's HP to drop below half, it switches out.", species = 1, expressible = false },
  { id = "EMERGENCYEXIT", n = 194, slug = "emergency-exit", name = "Emergency Exit", generation = 7, shortEffect = "This Pokémon automatically switches out when its HP drops below half.", effect = "After this Pokémon is hit by a move, if that move caused this Pokémon's HP to drop below half, it switches out.", species = 1, expressible = false },
  { id = "WATERCOMPACTION", n = 195, slug = "water-compaction", name = "Water Compaction", generation = 7, shortEffect = "Raises this Pokémon's Defense by two stages when it's hit by a Water move.", effect = "Raises this Pokémon's Defense by two stages when it's hit by a Water move.", species = 2, behaviour = { trigger = "on_hit_by", scope = "self", effects = { { kind = "stat_change", stat = "defense", stages = 2, when = "hit by a Water-type move" } } }, expressible = true },
  { id = "MERCILESS", n = 196, slug = "merciless", name = "Merciless", generation = 7, shortEffect = "This Pokémon's moves critical hit against poisoned targets.", effect = "This Pokémon's moves critical hit against poisoned targets.", species = 2, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "crit_change", always = true } } }, expressible = false, notes = "against a poisoned target" },
  { id = "SHIELDSDOWN", n = 197, slug = "shields-down", name = "Shields Down", generation = 7, shortEffect = "Transforms this Minior between Core Form and Meteor Form. Prevents major status ailments and drowsiness while in Meteor Form.", effect = "When this Pokémon enters battle and at the end of each turn, if its HP is 50% or above, it changes into Meteor Form; otherwise, it changes into Core Form. In Meteor Form, it cannot be given a major status ailment (though existing ones are not cured), cannot become drowsy from Yawn, and cannot use Rest (which will simply fail). This ability cannot be copied, replaced, or nullified. This ability only takes effect for Minior.", species = 14, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "status_immunity", status = "major" } } }, expressible = false, notes = "above half HP" },
  { id = "STAKEOUT", n = 198, slug = "stakeout", name = "Stakeout", generation = 7, shortEffect = "This Pokémon's moves have double power against Pokémon that switched in this turn.", effect = "This Pokémon's moves have double power against Pokémon that switched in this turn.", species = 9, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 2 } } }, expressible = false, notes = "against a Pokemon that switched in this turn" },
  { id = "WATERBUBBLE", n = 199, slug = "water-bubble", name = "Water Bubble", generation = 7, shortEffect = "Halves damage from Fire moves, doubles damage of Water moves, and prevents burns.", effect = "When this Pokémon is hit by a Fire move, the damage is halved. When this Pokémon uses a Water move, the power is doubled. This Pokémon cannot be burned, and if it becomes burned, the burn is immediately cured.", species = 3, behaviour = { trigger = "passive", scope = "self", effects = { { kind = "damage_dealt_multiplier", factor = 2, moveType = "WATER" }, { kind = "damage_taken_multiplier", factor = 0.5, moveType = "FIRE" }, { kind = "status_immunity", status = "burn" } } }, expressible = true },
