  { id = "DISGUISE", n = 209, slug = "disguise", name = "Disguise", generation = 7, shortEffect = "Prevents the first instance of battle damage.", effect = "If this Pokémon is in its Disguised Form and takes damage from a move, it switches to its Busted Form and the damage is prevented. Other effects are not prevented. This ability cannot be copied or replaced. This ability only takes effect for Mimikyu.", species = 4, expressible = false },
