  { id = "FULLMETALBODY", n = 230, slug = "full-metal-body", name = "Full Metal Body", generation = 7, shortEffect = "Other Pokémon cannot lower this Pokémon's stats.", effect = "This Pokémon's stats cannot be lowered by other Pokémon's moves or abilities. This effect only applies to normal stat modifications and not more exotic effects such as Topsy-Turvy or Power Swap. This Ability is not bypassed by Mold Breaker, Teravolt, or Turboblaze.", species = 1, expressible = false },
