  { id = "ICEFACE", n = 248, slug = "ice-face", name = "Ice Face", generation = 8, shortEffect = "The Pokémon’s ice head can take a physical attack as a substitute, but the attack also changes the Pokémon’s appearance. The ice will be restored when it snows.", effect = "When an Eiscue that's in its Ice Face form is hit by a physical move, it takes no damage and changes into its Noice Face form. If a hailstorm or snowstorm begins while Eiscue is in its Noice Face form, or if it is sent out in its Noice Face form during hail, it will immediately revert to its Ice Face form.", species = 2, expressible = false },
  { id = "POWERSPOT", n = 249, slug = "power-spot", name = "Power Spot", generation = 8, shortEffect = "Just being next to the Pokémon powers up moves.", effect = "\"The power of moves used by the allies of the Pokémon with Power Spot is increased by 30%.\"", species = 1, behaviour = { trigger = "passive", scope = "allies", effects = { { kind = "damage_dealt_multiplier", factor = 1.3 } } }, expressible = true },
